"""Build the complete, offline curriculum and Obsidian vault from reviewed content.

All paths are relative to the current workspace. This is not LLM extraction.
The source question text is separately retained with PDF page references.
"""
from pathlib import Path
import json, re

ROOT = Path.cwd()
concepts = []

def c(name, group, symbol, deps, meaning, formal, example, prompt, correct, wrong, hint, aliases=None):
    concepts.append(dict(id=re.sub(r'[^a-z0-9]+', '-', name.lower()).strip('-'), name=name,
        group=group, symbol=symbol, prerequisites=deps.split('|') if deps else [],
        meaning=meaning, formal=formal, example=example,
        aliases=aliases or [], check=dict(prompt=prompt, options=[correct]+wrong,
        correct=0, explanation=hint), verify=False))

# Ground concepts: precisely the stopping points authorized by the learner.
c('Real Number','ground',r'\mathbb R','','A number placed on the usual number line.',r'Real numbers include integers, fractions, and numbers such as $\sqrt{2}$ and $\pi$.',r'$-2,\ 0,\ 1/2,\ \sqrt2$ are real numbers.','Which number is real?',r'$\sqrt{2}$',[r'$i$',r'$2+i$'],'Real numbers lie on the ordinary number line.', ['number','real numbers'])
c('Integer','ground',r'\mathbb Z','','A whole number, including zero and negative whole numbers.',r'Integers are $\ldots,-2,-1,0,1,2,\ldots$.',r'$-3$ is an integer; $1/2$ is not.','Which is an integer?',r'$-3$',[r'$0.5$',r'$\sqrt{2}$'],'Integers have no fractional part.')
c('Basic Algebra','ground',r'x','','Rules for working with numbers, letters, sums, and products.',r'Use arithmetic, substitution, and equations, for example $a(b+c)=ab+ac$.',r'$2x=6$ gives $x=3$.','Solve $2x=6$.',r'$x=3$',[r'$x=12$',r'$x=2$'],'Divide both sides by 2.')
c('Set','ground',r'\{\ \}','','A collection of objects.',r'$x\in S$ means that $x$ belongs to the set $S$.',r'$S=\{1,2,3\}$ contains three numbers.',r'What does $x\in S$ say?','x belongs to S',['x equals S','S contains no x'],'The symbol means membership.')
c('Function','ground',r'f(x)','','A rule that assigns one output to each allowed input.',r'A function $f$ sends an input $x$ to a single output $f(x)$.',r'$f(x)=x^2$ sends $3$ to $9$.','If $f(x)=x^2$, what is $f(3)$?',r'$9$',[r'$6$',r'$3$'],'Substitute 3 into the rule.')
c('Coordinate','ground',r'x_1','','A number specifying a location relative to a chosen reference.',r'The coordinates $(x_1,x_2)$ locate a point using two chosen directions.',r'$(2,3)$ is two units across and three units up.','How many coordinates are in $(2,3)$?','Two',['One','Three'],'Count the entries.')
c('Complex Number Arithmetic','ground',r'i','','Arithmetic with numbers of the form $a+ib$, where $i^2=-1$.',r'For real $a,b$, add and multiply $a+ib$ using ordinary algebra and $i^2=-1$.',r'$(1+i)(1-i)=2$.','What is $i^2$?',r'$-1$',[r'$1$',r'$i$'],'This is the defining rule for i.', ['complex number','complex numbers'])
c('Derivative','ground',r'\frac{d}{dx}','','The rate at which a function changes.',r'The derivative $df/dx$ measures local change of the output with input $x$.',r'$d(x^2)/dx=2x$.','What is $d(x^2)/dx$?',r'$2x$',[r'$x$',r'$x^3/3$'],'Use the school-level power rule.')
c('Integral','ground',r'\int','','A way to add continuously varying small contributions.',r'$\int_a^b f(x)\,dx$ adds the contributions $f(x)\,dx$ between $a$ and $b$.',r'$\int_0^1 x\,dx=1/2$.',r'What is $\int_0^1 x\,dx$?',r'$1/2$',[r'$1$',r'$2$'],'Evaluate x²/2 at the two endpoints.')

# Algebra and spaces. Definition direction deliberately avoids circular dependencies.
c('Absolute Value','ground',r'|z|','Complex Number Arithmetic|Real Number', 'The nonnegative size of a number.',r'For $z=a+ib$, its absolute value is $|z|=\sqrt{a^2+b^2}$.',r'$|3+4i|=5$.','What is $|3+4i|$?',r'$5$',[r'$7$',r'$1$'],'Use the square root of 3²+4².', ['modulus'])
c('Axiom','spaces',r'\therefore','Set','A starting rule accepted in a mathematical definition.',r'An axiom states a rule assumed for the objects under discussion; other conclusions follow from those rules.',r'One rule for addition is $u+v=v+u$.','An axiom is…','A starting rule',['A measured quantity','A coordinate'],'It supplies a starting point for deductions.')
c('Field','spaces',r'\mathbb F','Set|Real Number|Complex Number Arithmetic|Basic Algebra','A collection of numbers where addition, subtraction, multiplication, and division by nonzero numbers work.',r'A field is a set with addition and multiplication, associative and commutative, with $0$, $1\ne0$, additive inverses, multiplicative inverses for nonzero elements, and $a(b+c)=ab+ac$.',r'$\mathbb R$ and $\mathbb C$ are fields; integers fail because $1/2$ is not an integer.','Why are integers not a field?','Division can leave the integers',['Addition is impossible','There is no zero'],'2 has no integer multiplicative inverse.')
c('Scalar','spaces',r'\alpha','Field','A number used to scale an object.',r'A scalar is an element of the field of numbers used for the vector space.',r'In $3(1,2)=(3,6)$, $3$ is the scalar.','What is the scalar in $3(1,2)$?',r'$3$',[r'$(1,2)$',r'$(3,6)$'],'It is the multiplying number.')
c('Vector','spaces',r'\vec v','Scalar|Coordinate|Set','An object that can be added to another of its kind and multiplied by a number.',r'For a coordinate example, $v=(v_1,\ldots,v_n)$ has scalar entries; addition and scaling act entry by entry. Abstract vectors may instead be functions or state symbols with specified addition and scaling.',r'$(1,2)+(3,4)=(4,6)$.','What is $(1,2)+(3,4)$?',r'$(4,6)$',[r'$(3,8)$',r'$(1,4)$'],'Add matching coordinates.', ['vectors'])
c('Closure','spaces',r'\circlearrowleft','Set|Vector|Scalar','Combining allowed objects produces another allowed object.',r'A set $V$ is closed under addition and scalar multiplication when $u+v\in V$ and $av\in V$ for all $u,v\in V$ and allowed scalars $a$.',r'Real coordinate pairs stay real coordinate pairs after addition.','Closure under addition means…',r'$u+v\in V$ whenever $u,v\in V$',[r'$u+v=0$ always',r'$u=v$ always'],'The result must stay in the set.')
c('Zero Vector','spaces',r'\mathbf0','Vector','The vector that leaves another vector unchanged when added.',r'$v+0=v$ for every vector $v$.',r'In two coordinates the zero vector is $(0,0)$.','Which is the zero vector in two coordinates?',r'$(0,0)$',[r'$(1,1)$',r'$(0,1)$'],'Both entries must be zero.')
c('Additive Inverse','spaces',r'-v','Zero Vector','A vector that cancels another vector when added.',r'For every vector $v$, its additive inverse $-v$ satisfies $v+(-v)=0$.',r'The inverse of $(2,-1)$ is $(-2,1)$.','What cancels $(2,-1)$?',r'$(-2,1)$',[r'$(2,1)$',r'$(-2,-1)$'],'Reverse the sign of each coordinate.')
c('Vector Space','spaces',r'V','Vector|Field|Axiom|Closure|Zero Vector|Additive Inverse','A collection of vectors that obey consistent rules for addition and scaling.',r'A vector space $V$ over a field $F$ is closed under addition and scalar multiplication. Addition is associative and commutative, has a zero vector and additive inverses; $a(u+v)=au+av$, $(a+b)v=av+bv$, $(ab)v=a(bv)$, and $1v=v$.',r'$\mathbb C^2$ with entrywise operations is a vector space. The set of positive real numbers is not: it lacks zero and negatives.','Which fails to be a vector space over the reals?','The positive real numbers',[r'$\mathbb R^2$',r'$\mathbb R$'],'Check zero and additive inverses.', ['linear vector space','linear space'])
c('Linear Combination','spaces',r'\sum a_iv_i','Vector Space','A sum of vectors after multiplying each by a number.',r'$a_1v_1+\cdots+a_nv_n$ is a linear combination with scalar coefficients $a_i$.',r'$2(1,0)+3(0,1)=(2,3)$.','Which is a linear combination?',r'$2u+3v$',[r'$u\times v$',r'$u/v$'],'It uses only addition and scalar multiplication.')
c('Linear Independence','spaces',r'\nparallel','Linear Combination|Zero Vector','No vector in the collection can be made from the others.',r'$v_1,\ldots,v_n$ are linearly independent if $\sum_i a_iv_i=0$ implies every $a_i=0$.',r'$(1,0)$ and $(0,1)$ are independent; $(1,0)$ and $(2,0)$ are not.','Are $(1,0)$ and $(2,0)$ independent?','No; one is twice the other',['Yes; they have different sizes','Yes; both are nonzero'],'A nontrivial combination 2v₁−v₂ gives zero.')
c('Span','spaces',r'\operatorname{span}','Linear Combination|Set','All vectors you can make from a given collection.',r'The span of $v_1,\ldots,v_n$ is the set of all their linear combinations.',r'The span of $(1,0)$ is the horizontal line.','What is the span of $(1,0)$?',r'All $(a,0)$',['All coordinate pairs','Only (1,0)'],'You can multiply by any allowed scalar.')
c('Basis','spaces',r'\{e_i\}','Linear Independence|Span','An independent collection from which every vector can be built.',r'A basis is a linearly independent set spanning the vector space; in finite dimensions every vector has a unique expansion in it.',r'$e_1=(1,0)$ and $e_2=(0,1)$ form a basis of $\mathbb R^2$.','A basis must…','Be independent and span the space',['Contain every vector','Contain the zero vector'],'Both conditions are required.')
c('Dimension','spaces',r'n','Basis|Integer','The number of independent directions in a space.',r'The dimension of a finite-dimensional vector space is the number of vectors in any basis.',r'$\mathbb C^2$ has dimension $2$.',r'How many basis vectors does $\mathbb C^2$ need?','Two',['One','Four'],'Dimension counts vectors over the chosen field.')
c('Complex Conjugate','spaces',r'z^*','Complex Number Arithmetic','A complex number with the sign of its imaginary part reversed.',r'If $z=a+ib$, then $z^*=a-ib$; $(zw)^*=z^*w^*$.',r'$(2+3i)^*=2-3i$.','What is $(2+3i)^*$?',r'$2-3i$',[r'$-2+3i$',r'$-2-3i$'],'Only the imaginary part changes sign.', ['conjugation'])

# Inner products and Hilbert spaces.
c('Inner Product','spaces',r'\langle\phi|\psi\rangle','Vector Space|Complex Conjugate|Absolute Value','A rule that pairs two vectors and returns a number measuring their overlap.',r'Using the physics convention, $\langle u|av+bw\rangle=a\langle u|v\rangle+b\langle u|w\rangle$, $\langle u|v\rangle=\langle v|u\rangle^*$, and $\langle v|v\rangle\ge0$, with equality only for $v=0$. In $\mathbb C^n$, $\langle u|v\rangle=\sum_i u_i^*v_i$.',r'For $u=(1,i)$, $v=(2,1)$, $\langle u|v\rangle=2-i$.',r'Which entry gets conjugated in $\langle u|v\rangle$?','The entries of u',['The entries of v','Both sets of entries'],'The physics convention is conjugate-linear in the first slot.', ['scalar product','Inner Product (Scalar Product)'])
c('Conjugate Symmetry','spaces',r'\langle u|v\rangle^*','Inner Product','Swapping the two vectors conjugates their overlap.',r'$\langle u|v\rangle=\langle v|u\rangle^*$.',r'If $\langle u|v\rangle=2+i$, then $\langle v|u\rangle=2-i$.',r'If $\langle u|v\rangle=i$, what is $\langle v|u\rangle$?',r'$-i$',[r'$i$',r'$1$'],'Conjugate the scalar product.')
c('Norm','spaces',r'\|v\|','Inner Product','The length of a vector.',r'The norm induced by an inner product is $\|v\|=\sqrt{\langle v|v\rangle}$.',r'$\|(3,4)\|=5$.',r'What is $\|(3,4)\|$?',r'$5$',[r'$7$',r'$25$'],'Take the square root of the self-inner-product.')
c('Orthogonality','spaces',r'\perp','Inner Product','Two vectors have zero overlap.',r'$u$ and $v$ are orthogonal when $\langle u|v\rangle=0$.',r'$(1,0)$ and $(0,1)$ are orthogonal.','Orthogonal vectors have which inner product?',r'$0$',[r'$1$',r'$-1$'],'Zero overlap defines orthogonality.', ['orthogonal'])
c('Normalization','spaces',r'\|\psi\|=1','Norm','Scaling a nonzero vector so its length is one.',r'For nonzero $v$, the normalized vector is $v/\|v\|$.',r'$(3,4)/5=(3/5,4/5)$.','Normalize $(3,4)$.',r'$(3/5,4/5)$',[r'$(3/25,4/25)$',r'$(1,1)$'],'Divide the vector by its norm.', ['normalized','normalisation'])
c('Orthonormal Basis','spaces',r'\delta_{ij}','Basis|Orthogonality|Normalization','A basis of unit-length vectors that have zero overlap with each other.',r'$\langle e_i|e_j\rangle=\delta_{ij}$, where the number $\delta_{ij}$ is 1 if $i=j$ and 0 otherwise. These vectors form a basis.',r'$(1,0),(0,1)$ form an orthonormal basis.',r'For $i\ne j$, what is $\langle e_i|e_j\rangle$?',r'$0$',[r'$1$',r'$i$'],'Different basis vectors are orthogonal.')
c('Sequence','spaces',r'(v_n)','Function|Integer','An ordered list indexed by counting numbers.',r'A sequence is a function assigning an object $v_n$ to each positive integer $n$.',r'$1,1/2,1/3,\ldots$ is a sequence.','What indexes a sequence?','Positive integers',['Only fractions','Only complex numbers'],'The index counts entries.')
c('Limit','spaces',r'\lim','Sequence|Absolute Value','A value that a sequence approaches arbitrarily closely.',r'$x_n\to L$ means for every real $\epsilon>0$, some integer $N$ has $|x_n-L|<\epsilon$ for all $n>N$.',r'$1/n\to0$.','What is the limit of $1/n$ as $n$ grows?',r'$0$',[r'$1$',r'$\infty$'],'The entries approach zero without needing to reach it.')
c('Convergence','spaces',r'v_n\to v','Sequence|Norm|Limit','The terms of a sequence approach a vector in distance.',r'A sequence $v_n$ converges in norm to $v$ if $\|v_n-v\|\to0$.',r'$(1/n,0)$ converges to $(0,0)$.','Norm convergence requires…',r'$\|v_n-v\|\to0$',[r'$\|v_n\|\to\infty$',r'$v_n=v$ for every n'],'Measure distance from the candidate limit.')
c('Cauchy Sequence','spaces',r'\|v_n-v_m\|','Sequence|Norm|Real Number','A sequence whose later terms get arbitrarily close to each other.',r'For every $\epsilon>0$, there is $N$ with $\|v_n-v_m\|<\epsilon$ whenever $n,m>N$.',r'The partial sums of $\sum_{k=1}^{\infty}2^{-k}$ are Cauchy.','A Cauchy condition compares…','Two sufficiently late terms',['Only the first and last term','Every term with zero'],'It does not assume a limit is already in the space.')
c('Complete Space','spaces',r'\overline V=V','Cauchy Sequence|Convergence','A space with no missing limits of Cauchy sequences.',r'A normed space is complete when every Cauchy sequence in it converges to an element of the same space.',r'Rational numbers are incomplete: rational approximations can approach $\sqrt2$, which is not rational.','Complete means every Cauchy sequence…','Converges within the space',['Has finitely many terms','Is constantly zero'],'The location of the limit matters.', ['completeness'])
c('Hilbert Space','spaces',r'\mathcal H','Vector Space|Inner Product|Complete Space','A vector space with an overlap rule and no missing limits measured by that rule.',r'A Hilbert space is an inner-product vector space complete in the induced norm $\|v\|=\sqrt{\langle v|v\rangle}$.',r'$\mathbb C^2$ with its usual inner product is a Hilbert space.','What extra condition makes an inner-product space Hilbert?','Completeness in its induced norm',['Dimension must be 2','All vectors must have length 1'],'Every Cauchy sequence must converge inside it.')

# State notation and operators.
c('Ket','states',r'|\psi\rangle','Vector|Hilbert Space','A notation for a quantum state vector.',r'$|\psi\rangle$ denotes a vector in the Hilbert space. In a chosen basis it can be represented as a column of coefficients.',r'$|\psi\rangle=\begin{pmatrix}1\\i\end{pmatrix}/\sqrt2$.','A ket represents…','A vector',['A real eigenvalue','Only a probability'],'The bracket is notation for a state vector.', ['state vector'])
c('Bra','states',r'\langle\psi|','Ket|Inner Product|Complex Conjugate','The rule associated with a ket that takes another ket and returns their overlap.',r'The bra $\langle\psi|$ maps $|\phi\rangle$ to $\langle\psi|\phi\rangle$. For coordinates $\begin{pmatrix}a\\b\end{pmatrix}$, its row is $(a^*,b^*)$.',r'The bra of $\begin{pmatrix}1\\i\end{pmatrix}$ is $(1,-i)$.',r'The bra of $\begin{pmatrix}1\\i\end{pmatrix}$ is…',r'$(1,-i)$',[r'$(1,i)$',r'$(-1,i)$'],'Transpose and conjugate the coordinates.')
c('Linear Operator','operators',r'\hat A','Vector Space|Function|Linear Combination','A rule taking vectors to vectors while respecting addition and scaling.',r'$A(a|u\rangle+b|v\rangle)=aA|u\rangle+bA|v\rangle$. The input vectors must belong to the operator domain.',r'$A(x,y)=(2x,3y)$ is linear. $A(x)=x^2$ is not linear over real numbers.','Which rule is linear?',r'$A(x)=3x$',[r'$A(x)=x^2$',r'$A(x)=x+1$'],'Check addition and scalar multiplication.', ['operator'])
c('Operator Domain','operators',r'D(A)','Set|Linear Operator','The set of vectors on which an operator is defined.',r'$D(A)$ is the set of allowed inputs of $A$. For a derivative on square-integrable functions, extra differentiability and boundary conditions are required.',r'Not every square-integrable function has a square-integrable derivative.','Is a derivative defined on every square-integrable function?','No, extra conditions are needed',['Yes, automatically','Only on constants'],'Some such functions are not differentiable.')
c('Operator Product','operators',r'AB','Linear Operator','Apply one operator and then another.',r'$(AB)|v\rangle=A(B|v\rangle)$ wherever both applications are defined. The rightmost operator acts first.',r'If $B(x)=2x$ and $A(x)=3x$, then $AB(x)=6x$.',r'In $AB|\psi\rangle$, which acts first?','B',['A','Both independently'],'Read composition from right to left.')
c('Identity Operator','operators',r'I','Linear Operator','The operator that leaves every vector unchanged.',r'$I|v\rangle=|v\rangle$.',r'Its two-dimensional matrix has diagonal entries 1 and off-diagonal entries 0.',r'What is $I|v\rangle$?',r'$|v\rangle$',[r'$0$',r'$-|v\rangle$'],'Identity means no change.')
c('Hermitian Adjoint','operators',r'A^\dagger','Linear Operator|Inner Product|Bra','The operator obtained by moving an operation across an inner product.',r'$\langle u|Av\rangle=\langle A^\dagger u|v\rangle$ for allowed vectors. For matrices, $(A^\dagger)_{ij}=A_{ji}^*$.',r'For $A=\begin{pmatrix}1&i\\2&3\end{pmatrix}$, $A^\dagger=\begin{pmatrix}1&2\\-i&3\end{pmatrix}$.','How do you find a matrix adjoint?','Transpose and complex-conjugate',['Only transpose','Only negate'],'Both operations are necessary.', ['adjoint','conjugate transpose'])
c('Hermitian Operator','operators',r'A=A^\dagger','Hermitian Adjoint','An operator equal to its adjoint in the setting under consideration.',r'In finite dimensions, Hermitian means $A=A^\dagger$, equivalently $\langle u|Av\rangle=\langle Au|v\rangle$. For unbounded operators, distinguish this symmetry identity from self-adjointness, which also requires equality of domains.',r'$\begin{pmatrix}2&-i\\i&3\end{pmatrix}$ is Hermitian.','A finite Hermitian matrix satisfies…',r'$A=A^\dagger$',[r'$A=-A^\dagger$',r'$A^2=0$'],'Match the matrix to its conjugate transpose.', ['Hermitian','Hermitian matrix'])
c('Self-adjoint Operator','operators',r'D(A)=D(A^\dagger)','Hermitian Operator|Operator Domain','An operator matching its adjoint in both action and allowed inputs.',r'$A=A^\dagger$ and $D(A)=D(A^\dagger)$. In finite dimensions this is the same as being Hermitian.',r'The momentum derivative requires a suitable domain and boundary conditions to be self-adjoint.','For an unbounded self-adjoint operator, domains must…','Coincide with the adjoint domain',['Be ignored','Contain only eigenvectors'],'Matching the formula alone is insufficient.')
c('Commutator','operators',r'[A,B]','Operator Product|Basic Algebra','The difference between applying two operators in opposite orders.',r'$[A,B]=AB-BA$. Commuting operators satisfy $[A,B]=0$. The product rule is $[A,BC]=[A,B]C+B[A,C]$.',r'$[x,p]=i\hbar I$ in the canonical position–momentum setting.','What is $[A,B]$?',r'$AB-BA$',[r'$AB+BA$',r'$BA$'],'It subtracts the reversed product.', ['commutation relation','commuting'])
c('Anticommutator','operators',r'\{A,B\}','Operator Product','The sum of two operator products in opposite orders.',r'$\{A,B\}=AB+BA$.',r'$\{A,A\}=2A^2$.',r'What is $\{A,A\}$?',r'$2A^2$',[r'$0$',r'$A^2$'],'Add the two identical products.')
c('Function of an Operator','operators',r'f(A)','Linear Operator|Function|Operator Product|Identity Operator','A function evaluated with an operator in place of its input.',r'For a polynomial, $f(A)=\sum_{n=0}^{N}c_nA^n$ with $A^0=I$. A power series requires convergence; more general definitions need a suitable spectral construction.',r'If $f(t)=t^2+2$, then $f(A)=A^2+2I$.','For $f(t)=t^2+2$, what is $f(A)$?',r'$A^2+2I$',[r'$2A$',r'$A+2$'],'The constant term multiplies the identity.')
c('Eigenvector','eigen',r'|a\rangle','Linear Operator|Scalar|Zero Vector','A nonzero vector whose direction stays the same under an operator.',r'$A|v\rangle=\lambda|v\rangle$ with $|v\rangle\ne0$ makes $|v\rangle$ an eigenvector.',r'For $A=\operatorname{diag}(2,3)$, $\begin{pmatrix}1\\0\end{pmatrix}$ is an eigenvector.','Can the zero vector be an eigenvector?','No',['Yes, always','Only for zero eigenvalues'],'Nonzero is part of the definition.')
c('Eigenvalue','eigen',r'\lambda','Eigenvector','The factor by which an operator scales an eigenvector.',r'If $A|v\rangle=\lambda|v\rangle$ for nonzero $|v\rangle$, then $\lambda$ is its eigenvalue.',r'$A\begin{pmatrix}1\\0\end{pmatrix}=2\begin{pmatrix}1\\0\end{pmatrix}$ gives eigenvalue $2$.',r'If $Av=3v$ and $v\ne0$, the eigenvalue is…',r'$3$',[r'$v$',r'$0$'],'Read the multiplying scalar.')
c('Degeneracy','eigen',r'g_\lambda','Eigenvalue|Linear Independence','Several independent eigenvectors share the same eigenvalue.',r'An eigenvalue is degenerate if its eigenspace, the set of its eigenvectors together with zero, has dimension greater than 1.',r'$A=2I$ on $\mathbb C^2$ has eigenvalue 2 with degeneracy 2.','For $2I$ in two dimensions, the degeneracy of 2 is…',r'$2$',[r'$1$',r'$0$'],'There are two independent eigenvectors.', ['degenerate eigenvalue','degenerate'])
c('Simultaneous Eigenvectors','eigen',r'|a,b\rangle','Eigenvalue|Commutator|Hermitian Operator|Degeneracy','Vectors that are eigenvectors of both operators.',r'Finite-dimensional commuting Hermitian operators admit a common orthonormal eigenbasis. A nondegenerate eigenvector of $A$ is also an eigenvector of $B$; within a degenerate eigenspace choose a basis diagonalizing $B$. Commutation alone does not give this result for arbitrary defective operators.',r'Two diagonal matrices share the coordinate basis.','With degeneracy, does every eigenvector of A automatically diagonalize B?','No; choose a common basis within each eigenspace',['Yes, every choice works','No common basis can exist'],'B may mix vectors inside a degenerate eigenspace.')
c('Projection Operator','eigen',r'|n\rangle\langle n|','Ket|Bra|Normalization|Operator Product','An operator that keeps a selected component of a vector.',r'For normalized $|n\rangle$, $P_n=|n\rangle\langle n|$ and $P_n^2=P_n=P_n^\dagger$.',r'$P_1\begin{pmatrix}a\\b\end{pmatrix}=\begin{pmatrix}a\\0\end{pmatrix}$.',r'What does $|1\rangle\langle1|$ keep?','The component along |1⟩',['Every component','Only the second component'],'It takes an overlap and rebuilds that direction.')
c('Completeness Relation','spaces',r'\sum_n|n\rangle\langle n|=I','Orthonormal Basis|Projection Operator|Identity Operator','Adding all basis-component projections reconstructs every vector.',r'For a complete orthonormal basis, $\sum_n|n\rangle\langle n|=I$ and $|\psi\rangle=\sum_n|n\rangle\langle n|\psi\rangle$. Infinite sums converge in the Hilbert-space norm.',r'In two dimensions $|1\rangle\langle1|+|2\rangle\langle2|=I$.','The sum of all orthonormal basis projections equals…',r'$I$',[r'$0$',r'$2I$'],'All components together reconstruct the state.')
c('Spectral Theorem','eigen',r'A=UDU^\dagger','Hermitian Operator|Eigenvalue|Orthonormal Basis|Completeness Relation','A finite Hermitian matrix has a complete orthonormal set of eigenvectors.',r'For an $n\times n$ Hermitian matrix, there is an orthonormal eigenbasis with real eigenvalues and $A=\sum_j\lambda_j|j\rangle\langle j|$. In infinite dimensions a self-adjoint operator has a spectral measure; normalizable eigenvectors need not form a discrete basis.',r'$\operatorname{diag}(2,3)=2P_1+3P_2$.','Does every infinite-dimensional observable have a discrete normalizable eigenbasis?','No; a continuous spectrum may occur',['Yes, always','Only if its eigenvalues are real'],'Position is a standard continuous-spectrum example.')

# Matrices and representations.
c('Matrix','matrices',r'\begin{pmatrix}a&b\\c&d\end{pmatrix}','Coordinate|Scalar|Basic Algebra','A rectangular array of numbers.',r'A matrix $A$ has entries $A_{ij}$, with row $i$ and column $j$. Products satisfy $(AB)_{ij}=\sum_k A_{ik}B_{kj}$.',r'$\begin{pmatrix}2&0\\0&3\end{pmatrix}\begin{pmatrix}a\\b\end{pmatrix}=\begin{pmatrix}2a\\3b\end{pmatrix}$.','What does the second index of $A_{ij}$ specify?','Column',['Row','Eigenvalue'],'The convention is row first, column second.')
c('Matrix Representation','matrices',r'A_{ij}','Matrix|Orthonormal Basis|Ket|Bra|Linear Operator','Numbers describing a state or operator in a chosen basis.',r'State coordinates are $c_i=\langle i|\psi\rangle$. Operator entries are $A_{ij}=\langle i|A|j\rangle$, so column $j$ contains the coordinates of $A|j\rangle$.',r'$A|1\rangle=2|1\rangle+i|2\rangle$ gives first column $\begin{pmatrix}2\\i\end{pmatrix}$.',r'Where do the coefficients of $A|1\rangle$ go?','The first column',['The first row','The diagonal only'],'The input basis index labels the column.')
c('Unitary Operator','matrices',r'U^\dagger U=I','Hermitian Adjoint|Identity Operator|Inner Product','An invertible operator that preserves overlaps and lengths.',r'$U^\dagger U=UU^\dagger=I$; hence $U^{-1}=U^\dagger$ and $\langle Uu|Uv\rangle=\langle u|v\rangle$.',r'A real rotation matrix is unitary.','For a unitary U, its inverse is…',r'$U^\dagger$',[r'$-U$',r'$U^2$'],'Its adjoint reverses the transformation.', ['unitary transformation'])
c('Change of Basis','matrices',r'A\mapsto U^\dagger AU','Matrix Representation|Unitary Operator','Describe the same object using different reference vectors.',r'If $|e_j\rangle=\sum_i|i\rangle U_{ij}$, with columns the new orthonormal basis in old coordinates, then $c_{new}=U^\dagger c_{old}$ and $A_{new}=U^\dagger A_{old}U$.',r'Taking new basis vectors to be eigenvectors produces a diagonal operator matrix.','When U has new basis vectors as columns, the new matrix is…',r'$U^\dagger AU$',[r'$UAU$',r'$A+U$'],'Convert new coordinates to old, act, then convert back.')
c('Determinant','matrices',r'\det A','Matrix|Basic Algebra','A number that detects whether a square matrix can be inverted.',r'For $A=\begin{pmatrix}a&b\\c&d\end{pmatrix}$, $\det A=ad-bc$. More generally, it is the signed sum over all permutations of column choices. $\det A=0$ exactly when a finite square matrix has a nonzero vector sent to zero.',r'$\det\begin{pmatrix}2&1\\1&3\end{pmatrix}=5$.',r'Compute the determinant of $\begin{pmatrix}2&1\\1&3\end{pmatrix}$.',r'$5$',[r'$6$',r'$7$'],'Multiply the diagonal entries and subtract the other product.')
c('Secular Equation','matrices',r'\det(A-\lambda I)=0','Determinant|Eigenvalue|Identity Operator','The equation whose roots are matrix eigenvalues.',r'$A v=\lambda v$ with $v\ne0$ requires $\det(A-\lambda I)=0$.',r'For $A=\operatorname{diag}(2,3)$, $(2-\lambda)(3-\lambda)=0$.','Which equation gives eigenvalues?',r'$\det(A-\lambda I)=0$',[r'$\det A=1$',r'$A+\lambda I=0$'],'Move the eigenvalue term to the left.')
c('Trace','matrices',r'\operatorname{tr}A','Matrix|Eigenvalue','The sum of a square matrix’s diagonal entries.',r'$\operatorname{tr}A=\sum_i A_{ii}$. For finite square matrices, $\operatorname{tr}(AB)=\operatorname{tr}(BA)$, and the trace equals the sum of eigenvalues counted with multiplicity.',r'The trace of $\operatorname{diag}(2,3)$ is $5$.',r'What is the trace of $\begin{pmatrix}2&-i\\i&3\end{pmatrix}$?',r'$5$',[r'$1$',r'$6$'],'Add only the diagonal entries.')

# Functions, continuous bases, and Fourier analysis.
c('Exponential Function','waves',r'e^x','Function|Derivative|Complex Number Arithmetic','A function whose rate of change equals itself.',r'$d(e^x)/dx=e^x$, $e^{a+b}=e^ae^b$, and $e^{i\theta}=\cos\theta+i\sin\theta$.',r'$|e^{i\theta}|=1$ for real $\theta$.',r'For real $\theta$, what is $|e^{i\theta}|$?',r'$1$',[r'$0$',r'$\theta$'],'It lies on the unit circle.')
c('Square-Integrable Function','waves',r'L^2','Function|Integral|Absolute Value|Hilbert Space','A function whose squared size has a finite integral.',r'$f$ is square-integrable if $\int_{-\infty}^{\infty}|f(x)|^2dx<\infty$. Functions differing only on a set of zero length are identified. The resulting $L^2$ space is complete with $\langle f|g\rangle=\int f^*(x)g(x)dx$.',r'$e^{-|x|}$ is square-integrable; the constant function 1 on the whole line is not.','Which test determines square integrability?',r'$\int |f(x)|^2dx<\infty$',[r'$f(0)=0$',r'$\int f(x)dx=0$'],'Integrate the squared magnitude, not the function itself.', ['square integrable','L2'])
c('Probability Density','waves',r'\rho(x)','Function|Integral|Normalization','A nonnegative function whose integral over an interval gives probability.',r'$\rho(x)\ge0$, $\int\rho(x)dx=1$, and the probability in $[a,b]$ is $\int_a^b\rho(x)dx$. Density at a point is not itself an interval probability.',r'If $\rho(x)=1$ on $[0,1]$, the probability in $[0,1/4]$ is $1/4$.','Probability in an interval is…','The integral of density over it',['The density at one endpoint','Always zero'],'Accumulate the density across the interval.')
c('Wave Function','waves',r'\psi(x)','Ket|Square-Integrable Function|Probability Density','The coefficients of a state expressed using a continuous coordinate.',r'For a normalized state, $\psi(x)=\langle x|\psi\rangle$ and $|\psi(x)|^2$ is its position probability density. The overall phase does not change that density.',r'$\psi(x)=\sqrt a\,e^{-a|x|}$ with $a>0$ is normalized on the line.','The position probability density is…',r'$|\psi(x)|^2$',[r'$\psi(x)$',r'$\psi(x)^2$ without conjugation'],'Complex amplitudes need their absolute-value squared.', ['wavefunction'])
c('Distribution','waves',r'T[f]','Function|Integral|Derivative','An object defined by how it acts on smooth functions rather than by pointwise values.',r'A distribution is a linear, continuous rule on smooth test functions with compact support. The delta distribution acts as $\delta[f]=f(0)$. Compact support means the function vanishes outside some finite interval; continuity means small test-function changes give small output changes in this setting.',r'$\delta[x^2+1]=1$ when evaluated locally with a suitable test function.','A distribution is described through…','Its action on test functions',['Only its pointwise height','A list of eigenvalues'],'This lets us define delta without pretending it is an ordinary function.')
c('Delta Function','waves',r'\delta(x-a)','Distribution|Integral','An idealized point selector inside an integral.',r'The Dirac delta is a distribution defined by $\int\delta(x-a)f(x)dx=f(a)$ for suitable smooth test functions. It is not an ordinary finite-valued function.',r'$\int\delta(x-2)(x+1)dx=3$.',r'Evaluate $\int\delta(x-2)(x+1)dx$.',r'$3$',[r'$2$',r'$0$'],'The delta selects the value at x=2.', ['Dirac delta','delta-function'])
c('Continuous Basis','waves',r'|x\rangle','Ket|Delta Function|Completeness Relation|Integral','A continuously labelled family of generalized state symbols.',r'Position states obey $\langle x|x\prime\rangle=\delta(x-x\prime)$ and $\int|x\rangle\langle x|dx=I$; momentum states obey the corresponding $p$ relations. These are generalized states, not normalizable vectors of $L^2$.',r'A physical wavepacket can be expanded as $|\psi\rangle=\int\psi(x)|x\rangle dx$.','Are exact position kets normalizable L² vectors?','No; they are generalized states',['Yes; their norm is 1','Only at x=0'],'Their overlap uses a distribution, not a finite norm.')
c('Position Representation','waves',r'\langle x|\psi\rangle','Wave Function|Continuous Basis','Describe a quantum state using position as the input variable.',r'$\psi(x)=\langle x|\psi\rangle$. For a normalized state, $\int|\psi(x)|^2dx=1$.',r'A localized packet has a density concentrated in a small position interval.','The position wave function is…',r'$\langle x|\psi\rangle$',[r'$\langle\psi|x\rangle$ without conjugation',r'$\langle p|\psi\rangle$'],'Project the ket onto the position bra.', ['position-space wave function'])
c('Momentum Representation','waves',r'\langle p|\psi\rangle','Wave Function|Continuous Basis','Describe a quantum state using momentum as the input variable.',r'$\phi(p)=\langle p|\psi\rangle$; $|\phi(p)|^2dp$ is the probability in a small momentum interval.',r'A narrow momentum density describes a state with nearly definite momentum.','The momentum wave function is…',r'$\langle p|\psi\rangle$',[r'$\langle x|\psi\rangle$',r'$\langle\psi|p\rangle$ without conjugation'],'Use the momentum bra.', ['momentum-space wave function'])
c('Planck Constant','waves',r'\hbar','Real Number','The constant setting the size of quantum effects.',r'$\hbar=h/(2\pi)$ is the reduced Planck constant. It has units of action, energy multiplied by time.',r'$[x,p]=i\hbar I$.','How are h and ℏ related?',r'$\hbar=h/(2\pi)$',[r'$\hbar=2\pi h$',r'$\hbar=h^2$'],'ℏ is the reduced constant.', ['reduced Planck constant'])
c('Fourier Transform','waves',r'\mathcal F','Integral|Exponential Function|Position Representation|Momentum Representation|Planck Constant','A change from a function’s position description to its momentum description.',r'$\phi(p)=\frac1{\sqrt{2\pi\hbar}}\int e^{-ipx/\hbar}\psi(x)dx$ and $\psi(x)=\frac1{\sqrt{2\pi\hbar}}\int e^{ipx/\hbar}\phi(p)dp$. With this convention it preserves the norm; integrals are understood in the $L^2$ sense when needed.',r'A sharply localized position packet needs a broad spread of momentum components.','The forward position-to-momentum kernel is…',r'$e^{-ipx/\hbar}$',[r'$e^{ipx/\hbar}$',r'$e^{-px/\hbar}$'],'Our forward convention uses the negative imaginary phase.')
c('Position Operator','operators',r'\hat x','Linear Operator|Position Representation','The operator that multiplies a position wave function by its coordinate.',r'$(\hat x\psi)(x)=x\psi(x)$ on the domain with $x\psi\in L^2$.',r'Applied to $e^{-x^2}$ it gives $xe^{-x^2}$.','In position space, x̂ acts by…','Multiplication by x',['Differentiation','Fourier transformation'],'The coordinate is the position eigenvalue.')
c('Momentum Operator','operators',r'\hat p','Linear Operator|Derivative|Position Representation|Planck Constant','The operator that differentiates a position wave function with a quantum scale factor.',r'$(\hat p\psi)(x)=-i\hbar\,d\psi/dx$ on a suitable domain. A plane wave $e^{ipx/\hbar}$ satisfies $\hat p e^{ipx/\hbar}=p e^{ipx/\hbar}$.',r'$\hat p e^{ikx}=\hbar k e^{ikx}$.','In position space, p̂ acts as…',r'$-i\hbar\,d/dx$',[r'$i\hbar x$',r'$x$'],'Differentiate and multiply by −iℏ.')
c('Integration by Parts','waves',r'\int u\,dv','Integral|Derivative|Basic Algebra','Move a derivative from one factor to the other inside an integral.',r'$\int_a^b u(x)v\prime(x)dx=[uv]_a^b-\int_a^b u\prime(x)v(x)dx$.',r'Boundary terms vanish for suitably decaying functions on the whole line.','Integration by parts creates…','A boundary term and an integral with the derivative moved',['No boundary term ever','Only a new constant'],'Keep the boundary contribution until conditions remove it.')
c('Boundary Condition','waves',r'\psi(\pm\infty)','Function|Limit|Operator Domain','A restriction on a function at the edge of its allowed region.',r'Boundary conditions specify endpoint behavior, such as vanishing or periodic values. They help select the operator domain and justify removal of boundary terms.',r'Smooth decaying wave functions have zero boundary products at infinity.','When can a boundary term be dropped?','When the imposed boundary behavior makes it zero',['Always','Whenever the operator is linear'],'State the boundary assumption explicitly.')

# Statistics and uncertainty.
c('Observable','uncertainty',r'\hat A','Self-adjoint Operator|Eigenvalue','A measurable physical quantity represented by an appropriate operator.',r'Quantum observables are represented by self-adjoint operators, with measurement outcomes described by their spectra. In finite dimensions these are Hermitian matrices and their eigenvalues.',r'Position and momentum are observables.','In finite dimensions, observables use…','Hermitian matrices',['Arbitrary complex matrices','Only zero matrices'],'This ensures real possible outcomes.')
c('Expectation Value','uncertainty',r'\langle A\rangle','Observable|Inner Product|Normalization','The average predicted measurement result over many identical preparations.',r'For a normalized state, $\langle A\rangle=\langle\psi|A|\psi\rangle$. For an unnormalized vector divide by $\langle\psi|\psi\rangle$.',r'For $A=\operatorname{diag}(2,3)$ and $\psi=\begin{pmatrix}1\\1\end{pmatrix}/\sqrt2$, $\langle A\rangle=5/2$.','For equal probabilities of 2 and 3, the expectation is…',r'$2.5$',[r'$5$',r'$1$'],'Average the outcomes with their probabilities.')
c('Variance','uncertainty',r'(\Delta A)^2','Expectation Value|Operator Product','The mean squared distance of measurement results from their average.',r'$(\Delta A)^2=\langle(A-\langle A\rangle I)^2\rangle=\langle A^2\rangle-\langle A\rangle^2$.',r'Equal outcomes 2 and 4 have mean 3 and variance 1.','The variance of equally likely 2 and 4 is…',r'$1$',[r'$3$',r'$2$'],'Each squared deviation from 3 equals 1.', ['Variance (Uncertainty)'])
c('Standard Deviation','uncertainty',r'\Delta A','Variance','The nonnegative square root of the variance.',r'$\Delta A=\sqrt{\langle A^2\rangle-\langle A\rangle^2}$. It is the uncertainty used in the quantum uncertainty relation.',r'Variance 4 means standard deviation 2.','If variance is 4, uncertainty ΔA is…',r'$2$',[r'$4$',r'$16$'],'Take the nonnegative square root.', ['uncertainty'])
c('Schwarz Inequality','uncertainty',r'|\langle u|v\rangle|^2','Inner Product|Norm','The overlap of two vectors cannot exceed the product of their lengths.',r'$|\langle u|v\rangle|^2\le\langle u|u\rangle\langle v|v\rangle$. Equality holds exactly for linearly dependent vectors, including the zero-vector cases.',r'For orthogonal unit vectors, $0\le1$.','For unit vectors, the overlap magnitude is at most…',r'$1$',[r'$2$',r'$\infty$'],'Both self-inner-products are 1.', ['Cauchy–Schwarz inequality','Cauchy Schwarz'])
c('Covariance','uncertainty',r'\operatorname{Cov}(A,B)','Expectation Value|Anticommutator|Variance','The symmetric average of two centered observables multiplied together.',r'With $A\prime=A-\langle A\rangle I$ and $B\prime=B-\langle B\rangle I$, $\operatorname{Cov}(A,B)=\tfrac12\langle\{A\prime,B\prime\}\rangle$.',r'If $A=B$, covariance equals the variance of $A$.','For $A=B$, covariance becomes…','Variance',['Zero always','Trace'],'The centered product becomes the centered square.')
c('Uncertainty Relation','uncertainty',r'\Delta A\Delta B','Schwarz Inequality|Standard Deviation|Commutator','A lower bound on the product of two measurement spreads.',r'For suitable states and Hermitian operators with the required products defined, $\Delta A\Delta B\ge\tfrac12|\langle[A,B]\rangle|$. This is the Robertson bound.',r'Noncommuting operators can constrain how small both spreads are.','The Robertson lower bound is…',r'$\tfrac12|\langle[A,B]\rangle|',[r'$\langle A\rangle\langle B\rangle$',r'$\operatorname{tr}(AB)$'],'The expected commutator sets this bound.', ['Robertson uncertainty relation','general uncertainty relation'])
c('Robertson–Schrödinger Relation','uncertainty',r'\Delta A^2\Delta B^2','Uncertainty Relation|Covariance','A stronger uncertainty bound that also includes symmetric correlation.',r'$(\Delta A)^2(\Delta B)^2\ge\tfrac14|\langle[A,B]\rangle|^2+\operatorname{Cov}(A,B)^2$. Dropping the nonnegative covariance term gives the Robertson bound.',r'A nonzero covariance strengthens the lower bound.','Which extra term strengthens the Robertson bound?',r'$\operatorname{Cov}(A,B)^2$',[r'$\operatorname{tr}(A)$',r'$\langle A\rangle$'],'The symmetric correlation contributes a nonnegative square.', ['Robertson Schrodinger'])
c('Heisenberg Uncertainty Principle','uncertainty',r'\Delta x\Delta p\ge\hbar/2','Uncertainty Relation|Position Operator|Momentum Operator|Planck Constant','Position and momentum spreads cannot both be arbitrarily small.',r'Using $[x,p]=i\hbar I$ gives $\Delta x\Delta p\ge\hbar/2$ for normalized states with finite variances and suitable domains.',r'Halving a minimum-width position spread requires at least doubling the corresponding minimum momentum spread.','The position–momentum lower bound is…',r'$\hbar/2$',[r'$\hbar$',r'$0$'],'Insert the canonical commutator into Robertson.')

questions = []
def s(prompt, correct, a, b, explanation, term=None):
    return dict(prompt=prompt, options=[correct,a,b], correct=0, explanation=explanation, term=term)
def q(section, number, title, text, terms, answer, steps, page, flag=None):
    questions.append(dict(id=f'Q-{section}-{number}', section=section, number=number,
        title=title, text=text, terms=terms.split('|'), answer=answer.replace(r'\n', '\n'),
        steps=steps, page=page, source='Module3.pdf', verify=flag,
        type=('define' if section=='A' else 'derive / prove / compute'),
        marks_style={'A':'short','B':'medium','C':'long'}[section]))

q('A',1,'Linear vector space','Define a linear vector space and list any three properties that its vectors must satisfy.',
  'Vector Space|Vector|Scalar|Field|Closure|Axiom',
  r'A vector space $V$ over a field $F$ is a set of vectors closed under addition and scalar multiplication and satisfying the vector-space axioms. Any three properties: (i) $u+v=v+u$; (ii) $(u+v)+w=u+(v+w)$; (iii) a zero vector $0$ exists with $v+0=v$.',[
  s('First, what two operations must the space support?','Vector addition and scalar multiplication','Vector multiplication and division','Only addition','These are the two defining operations.','Vector Space'),
  s('What must happen when two allowed vectors are added?','The sum stays in the space','The sum is always zero','The sum becomes a scalar','This is closure under addition.','Closure'),
  s('Which equation states commutativity?',r'$u+v=v+u$',r'$(u+v)+w=u+(v+w)$',r'$v+0=v$','Swapping summands does not change the result.','Axiom'),
  s('Which gives the additive identity property?',r'$v+0=v$',r'$v+v=0$',r'$av=a$','The zero vector leaves every vector unchanged.','Zero Vector')],1)
q('A',2,'What makes a space Hilbert?','What is a Hilbert space? Mention the role of the scalar product in defining a Hilbert space.',
  'Hilbert Space|Inner Product|Norm|Complete Space',r'A Hilbert space is a vector space with an inner product, complete under its induced norm $\|v\|=\sqrt{\langle v|v\rangle}$. The scalar product defines overlaps, lengths, and the distance used for completeness.',[
  s('What structure measures overlap?','An inner product','A determinant','A trace','The scalar product pairs two vectors.','Inner Product'),
  s('What is still required after specifying an inner product?','Completeness in the induced norm','Every vector must be real','A two-dimensional basis','No Cauchy limits may be missing.','Complete Space')],1)
q('A',3,'Scalar product','Define the scalar product of two state vectors | ψ ⟩ and | ϕ ⟩ .',
  'Inner Product|Ket|Bra|Complex Conjugate',r'The scalar product $\langle\phi|\psi\rangle$ is the complex number obtained by pairing the bra of $|\phi\rangle$ with $|\psi\rangle$. In an orthonormal basis, $\langle\phi|\psi\rangle=\sum_n\phi_n^*\psi_n$; it is linear in the second slot, conjugate-symmetric, and positive on a nonzero vector paired with itself.',[
  s('Which coefficients are conjugated?',r'$\phi_n$',r'$\psi_n$','Neither','Use the bra of the first vector.','Inner Product'),
  s('What kind of object is the result?','A scalar','A ket','An operator','An overlap is a number.','Scalar')],1)
q('A',4,'Conjugate symmetry','State the conjugate symmetry property of the scalar product.',
  'Conjugate Symmetry|Inner Product|Complex Conjugate',r'$\langle\phi|\psi\rangle=\langle\psi|\phi\rangle^*$. Swapping the vectors complex-conjugates the inner product.',[
  s('When you swap the vectors, what changes?','Take the complex conjugate','Always negate the result','Nothing, even for complex values','Use conjugate symmetry.','Conjugate Symmetry')],1)
q('A',5,'Turn a ket into a bra','Write the bra corresponding to the ket |ψ> = a |Φ₁> + b |Φ₂>',
  'Bra|Ket|Complex Conjugate|Hermitian Adjoint',r'Taking the Hermitian adjoint gives $\langle\psi|=a^*\langle\Phi_1|+b^*\langle\Phi_2|$.',[
  s('First, what happens to a and b?','Complex-conjugate both','Leave them unchanged','Swap them','The bra is conjugate-linear in the ket coefficients.','Complex Conjugate'),
  s('Which is the resulting bra?',r'$a^*\langle\Phi_1|+b^*\langle\Phi_2|$',r'$a\langle\Phi_1|+b\langle\Phi_2|$',r'$b^*|\Phi_1\rangle+a^*|\Phi_2\rangle$','Convert kets to bras and conjugate the scalars.','Bra')],1)
q('A',6,'Hermitian adjoint','Define the Hermitian adjoint Â† of a linear operator Â in terms of inner products.\nState the condition under which an operator is strictly Hermitian.',
  'Hermitian Adjoint|Linear Operator|Inner Product|Hermitian Operator|Self-adjoint Operator',r'The adjoint is defined by $\langle u|Av\rangle=\langle A^\dagger u|v\rangle$. In finite dimensions, an operator is Hermitian when $A=A^\dagger$. For an unbounded self-adjoint operator, its domain must also equal the adjoint domain.',[
  s('Which identity defines the adjoint?',r'$\langle u|Av\rangle=\langle A^\dagger u|v\rangle$',r'$A^\dagger=-A$',r'$A^\dagger=A^{-1}$','Move A to the other slot as its adjoint.','Hermitian Adjoint'),
  s('For a finite matrix, when is it Hermitian?',r'$A=A^\dagger$',r'$A=I$',r'$A^2=A$','Equality with its adjoint is the criterion.','Hermitian Operator')],1)
q('A',7,'Commutator product rules','Using basic commutation relation [x, p] = iℏ evaluate [x, p²] and [x², p]',
  'Commutator|Position Operator|Momentum Operator|Planck Constant|Identity Operator',r'Using $[A,BC]=[A,B]C+B[A,C]$, $[x,p^2]=[x,p]p+p[x,p]=2i\hbar p$. Similarly $[x^2,p]=x[x,p]+[x,p]x=2i\hbar x$.',[
  s('What is the first step for $[x,p^2]$?',r'$[x,p]p+p[x,p]$',r'$[x,p][x,p]$',r'$x^2p-px^2$','Expand using the product rule.','Commutator'),
  s(r'After inserting $[x,p]=i\hbar I$, the result is…',r'$2i\hbar p$',r'$i\hbar p^2$',r'$0$','Each of the two terms equals iℏp.','Commutator'),
  s('What is $[x^2,p]$?',r'$2i\hbar x$',r'$2i\hbar p$',r'$-2i\hbar x$','Expand x² as a product.','Commutator')],1)
q('A',8,'Functions of operators','What is meant by a function f(Â) of an operator?',
  'Function of an Operator|Linear Operator|Identity Operator',r'For a polynomial $f(t)=\sum_{n=0}^N c_nt^n$, define $f(A)=\sum_{n=0}^N c_nA^n$, with $A^0=I$. Convergent power series and suitable spectral constructions extend this definition.',[
  s('If $f(t)=t^2+3$, what is $f(A)$?',r'$A^2+3I$',r'$A+3$',r'$3A^2$','Replace the variable by A and constants by multiples of I.','Function of an Operator')],1)
q('A',9,'An operator function on an eigenstate','If Â |α> = α |α> , what is f(Â)|α> ?',
  'Function of an Operator|Eigenvector|Eigenvalue|Ket',r'$f(A)|\alpha\rangle=f(\alpha)|\alpha\rangle$ whenever $f(A)$ is defined on this eigenvector. For a polynomial, use $A^n|\alpha\rangle=\alpha^n|\alpha\rangle$ term by term.',[
  s(r'If $A|\alpha\rangle=\alpha|\alpha\rangle$, what does $A^2$ give?',r'$\alpha^2|\alpha\rangle$',r'$2\alpha|\alpha\rangle$',r'$|\alpha\rangle$','Apply A twice.','Eigenvalue'),
  s('So what does $f(A)$ give?',r'$f(\alpha)|\alpha\rangle$',r'$\alpha f(|\alpha\rangle)$',r'$f(A)$ alone','Apply the scalar function to the eigenvalue.','Function of an Operator')],1)
q('A',10,'Common eigenvectors','What can be said about simultaneous eigenvectors of commuting operators?',
  'Simultaneous Eigenvectors|Commutator|Hermitian Operator|Degeneracy|Orthonormal Basis',r'Commuting Hermitian operators in a finite-dimensional space can be simultaneously diagonalized: a common orthonormal eigenbasis can be chosen. If an eigenvalue of one operator is degenerate, diagonalize the other within that eigenspace.',[
  s('Under the finite Hermitian assumptions, commuting operators admit…','A common orthonormal eigenbasis','Only different bases','No eigenvectors','Commutation preserves eigenspaces.','Simultaneous Eigenvectors'),
  s('What if an eigenspace is degenerate?','Diagonalize the other operator inside it','Choose any vector and it always works','Remove the eigenspace','A suitable shared basis can be chosen.','Degeneracy')],1, 'The common-eigenbasis statement needs assumptions such as finite-dimensional Hermitian operators; commutation alone is insufficient for arbitrary operators.')
q('A',11,'Degenerate eigenvalues','What is a degenerate eigenvalue?',
  'Degeneracy|Eigenvalue|Eigenvector|Linear Independence',r'An eigenvalue is degenerate when two or more linearly independent eigenvectors have that same eigenvalue. Its degeneracy is the dimension of the eigenspace.',[
  s('What must distinct eigenvectors share for degeneracy?','The same eigenvalue','The same coordinates','The same norm only','Independence plus a common eigenvalue is the key.','Degeneracy')],1)
q('A',12,'Position wave function','What is the position-space wave function of a state | ψ ⟩ ?',
  'Position Representation|Wave Function|Ket|Bra|Probability Density',r'The position-space wave function is $\psi(x)=\langle x|\psi\rangle$. For a normalized state, $|\psi(x)|^2dx$ is the probability of finding the particle in a small interval of width $dx$ around $x$.',[
  s('Which projection gives the position amplitude?',r'$\langle x|\psi\rangle$',r'$\langle p|\psi\rangle$',r'$\langle\psi|\psi\rangle$','Choose a position bra.','Position Representation')],1)
q('A',13,'Momentum wave function','What is the momentum-space wave function of a state |ψ ⟩ ?',
  'Momentum Representation|Wave Function|Ket|Bra|Probability Density',r'The momentum-space wave function is $\phi(p)=\langle p|\psi\rangle$. For a normalized state, $|\phi(p)|^2dp$ is the probability of finding momentum in a small interval of width $dp$.',[
  s('Which projection gives the momentum amplitude?',r'$\langle p|\psi\rangle$',r'$\langle x|\psi\rangle$',r'$\langle\psi|p\rangle$','Use the momentum bra.','Momentum Representation')],1)
q('A',14,'Connecting two representations','How are position and momentum wave functions connected?',
  'Fourier Transform|Position Representation|Momentum Representation|Planck Constant',r'They are a Fourier transform pair: $\phi(p)=(2\pi\hbar)^{-1/2}\int e^{-ipx/\hbar}\psi(x)dx$ and $\psi(x)=(2\pi\hbar)^{-1/2}\int e^{ipx/\hbar}\phi(p)dp$.',[
  s('Which transformation connects the two?','Fourier transform','Complex conjugation alone','Trace','It changes the continuous basis.','Fourier Transform'),
  s('What is the forward phase sign?','Negative in the exponent','Positive in both directions','No imaginary unit','The inverse uses the conjugate phase.','Fourier Transform')],1)
q('A',15,'Name the transformation','What mathematical transformation connects the position and momentum representations?',
  'Fourier Transform|Position Representation|Momentum Representation',r'The Fourier transform connects position and momentum representations, with the inverse Fourier transform returning to position space.',[
  s('Name the transformation.','Fourier transform','Matrix trace','Ordinary derivative','It resolves position amplitudes into momentum components.','Fourier Transform')],1)

q('B',1,'Why square integrability?','Explain why the set of square-integrable functions is suitable for representing wave functions.',
  'Square-Integrable Function|Wave Function|Probability Density|Normalization|Hilbert Space|Inner Product',r'1. A position wave function must have finite $\int|\psi(x)|^2dx$ so a nonzero state can be normalized to total probability 1.\n2. Square-integrable functions, identifying functions equal except on sets of zero length, form a vector space. Its inner product is $\langle\phi|\psi\rangle=\int\phi^*(x)\psi(x)dx$; the Schwarz inequality ensures it is finite.\n3. This space $L^2$ is complete under its induced norm, so it is a Hilbert space. Thus superpositions and norm limits remain valid state vectors. Idealized plane waves are generalized states rather than normalizable members of $L^2$.',[
  s('First, which integral controls total probability?',r'$\int|\psi|^2dx$',r'$\int\psi\,dx$',r'$\psi(0)$','Square the magnitude before integrating.','Square-Integrable Function'),
  s('What does finiteness allow for a nonzero function?','Normalization','A definite position','Zero uncertainty in everything','Scale it to unit norm.','Normalization'),
  s('What ensures the space has no missing norm limits?','Completeness','The trace','A single eigenvalue','L² is complete.','Hilbert Space')],2)
q('B',2,'Normalize an exponential','Show that the function ψ(x) = A e⁻ᵃ|ˣ|, a > 0, is square-integrable. Find the normalization constant A.',
  'Square-Integrable Function|Exponential Function|Absolute Value|Integral|Normalization|Complex Conjugate',r'1. $|\psi(x)|^2=|A|^2e^{-2a|x|}$.\n2. Split the integral at zero and use equal contributions on the two halves: $\int_{-\infty}^{\infty}|\psi|^2dx=2|A|^2\int_0^{\infty}e^{-2ax}dx=|A|^2/a<\infty$ for finite $A$ and $a>0$.\n3. Normalization requires $|A|^2/a=1$, so $|A|=\sqrt a$. Choosing the irrelevant global phase to be zero gives $A=\sqrt a$; generally $A=\sqrt a\,e^{i\theta}$.',[
  s(r'First, what is $|\psi|^2$?',r'$|A|^2e^{-2a|x|}$',r'$Ae^{-a|x|}$',r'$A^2e^{2a|x|}$','Conjugate and multiply.','Square-Integrable Function'),
  s('How can the whole-line integral be simplified?',r'$2\int_0^\infty$ of the same density',r'$\int_0^1$ only','Set x=0','The density is even.','Integral'),
  s('The integral evaluates to…',r'$|A|^2/a$',r'$|A|^2/(2a)$',r'$a|A|^2$','Each half contributes |A|²/(2a).','Integral'),
  s('Choosing real positive A, normalization gives…',r'$A=\sqrt a$',r'$A=a$',r'$A=1/\sqrt a$','Set the full integral equal to one.','Normalization')],2)
q('B',3,'Prove Schwarz inequality','Prove the Schwarz inequality: |⟨ϕ|ψ⟩|² ≤ ⟨ϕ|ϕ⟩ ⟨ψ|ψ⟩',
  'Schwarz Inequality|Inner Product|Norm|Complex Conjugate|Linear Combination|Orthogonality',r'1. If $|\phi\rangle=0$, both sides involving its norm are zero, so the inequality holds. Otherwise set $c=\langle\phi|\psi\rangle/\langle\phi|\phi\rangle$ and $|r\rangle=|\psi\rangle-c|\phi\rangle$.\n2. Positive definiteness of the inner product gives $0\le\langle r|r\rangle=\langle\psi|\psi\rangle-|\langle\phi|\psi\rangle|^2/\langle\phi|\phi\rangle$.\n3. Multiply by the positive number $\langle\phi|\phi\rangle$ to obtain $|\langle\phi|\psi\rangle|^2\le\langle\phi|\phi\rangle\langle\psi|\psi\rangle$. Equality holds when the nonzero vectors are linearly dependent, with zero-vector cases also giving equality.',[
  s('First, why separate the zero-vector case?','To avoid dividing by its zero norm','It has an infinite norm','It violates the inequality','The usual proof divides by the self-inner-product.','Norm'),
  s('For a nonzero ϕ, choose c as…',r'$\langle\phi|\psi\rangle/\langle\phi|\phi\rangle$',r'$\langle\psi|\phi\rangle$',r'$0$','Remove the projection along ϕ.','Inner Product'),
  s('Which starting inequality is used?',r'$\langle r|r\rangle\ge0$',r'$\langle r|r\rangle<0$',r'$\langle r|r\rangle=1$','Squared norms are nonnegative.','Schwarz Inequality'),
  s('When does equality hold?','For linearly dependent vectors','Only for orthogonal nonzero vectors','Never','The residual can then be zero.','Linear Independence')],2)
q('B',4,'When is AB Hermitian?','Show that if Â and B̂ are Hermitian, then ÂB̂ is Hermitian only if Â and B̂ commute.',
  'Hermitian Operator|Hermitian Adjoint|Operator Product|Commutator',r'1. For finite matrices, $(AB)^\dagger=B^\dagger A^\dagger$.\n2. Because $A$ and $B$ are Hermitian, $(AB)^\dagger=BA$.\n3. Therefore $AB$ is Hermitian exactly when $AB=(AB)^\dagger=BA$, or $[A,B]=0$. For unbounded operators, product domains require additional care.',[
  s('First, what is the adjoint of AB?',r'$B^\dagger A^\dagger$',r'$A^\dagger B^\dagger$',r'$AB$ always','Taking an adjoint reverses product order.','Hermitian Adjoint'),
  s('After using Hermiticity, it becomes…',r'$BA$',r'$AB$ without conditions',r'$-BA$','Replace each adjoint by the original operator.','Operator Product'),
  s('Thus AB is Hermitian when…',r'$[A,B]=0$',r'$[A,B]=I$',r'$A+B=0$','AB must equal BA.','Commutator')],2)
q('B',5,'General uncertainty bound','Derive the general uncertainty relation ΔÂ ΔB̂ ≥ ½ |⟨[Â, B̂]⟩|.',
  'Uncertainty Relation|Expectation Value|Variance|Standard Deviation|Schwarz Inequality|Commutator|Hermitian Operator',r'1. For normalized $|\psi\rangle$, set $A\prime=A-\langle A\rangle I$, $B\prime=B-\langle B\rangle I$, $|\alpha\rangle=A\prime|\psi\rangle$, $|\beta\rangle=B\prime|\psi\rangle$. Assume the required products are defined and variances finite.\n2. Schwarz gives $(\Delta A)^2(\Delta B)^2\ge|\langle A\prime B\prime\rangle|^2$.\n3. For Hermitian $A,B$, $\operatorname{Im}\langle A\prime B\prime\rangle=\langle[A,B]\rangle/(2i)$. The absolute-value squared is at least the imaginary-part squared.\n4. Taking nonnegative square roots yields $\Delta A\Delta B\ge\tfrac12|\langle[A,B]\rangle|$.',[
  s('First, how do we center A?',r'$A\prime=A-\langle A\rangle I$',r'$A\prime=A^2$',r'$A\prime=A+I$','Subtract the mean as an identity multiple.','Variance'),
  s('Which inequality is applied to the centered state vectors?','Schwarz inequality','Triangle equality','Trace invariance','It bounds the squared overlap.','Schwarz Inequality'),
  s('Which part of the overlap gives the commutator term?','Its imaginary part','Its real part only','Its norm denominator','Subtract the conjugate reversed product.','Commutator'),
  s('What is the final lower bound?',r'$\tfrac12|\langle[A,B]\rangle|$',r'$|\langle AB\rangle|^2$',r'$\langle A\rangle+\langle B\rangle$','Take the nonnegative square roots.','Uncertainty Relation')],2)
q('B',6,'Real eigenvalues','Prove that the eigenvalues of a Hermitian operator are real.',
  'Hermitian Operator|Eigenvalue|Eigenvector|Inner Product|Complex Conjugate|Norm',r'1. Let $A|v\rangle=\lambda|v\rangle$ with $v\ne0$. Then $\langle v|Av\rangle=\lambda\langle v|v\rangle$.\n2. Hermiticity gives $\langle v|Av\rangle=\langle Av|v\rangle=\lambda^*\langle v|v\rangle$.\n3. Hence $(\lambda-\lambda^*)\langle v|v\rangle=0$. The nonzero eigenvector has strictly positive squared norm, so $\lambda=\lambda^*$: the eigenvalue is real.',[
  s('First, what equation should you write?',r'$A|v\rangle=\lambda|v\rangle$, $v\ne0$',r'$A=I$',r'$\lambda=0$','Start with the eigenvalue definition.','Eigenvalue'),
  s('Move A across the inner product. Which scalar appears?',r'$\lambda^*$',r'$-\lambda$',r'$1/\lambda$','The first slot conjugates scalar factors.','Hermitian Operator'),
  s(r'Why can we cancel $\langle v|v\rangle$?','It is positive since v is nonzero','Every norm equals 1','Hermitian operators have no zero eigenvalue','Nonzero norm is enough.','Norm'),
  s(r'What does $\lambda=\lambda^*$ establish?','λ is real','λ is positive','λ is an integer','Real does not mean positive.','Complex Conjugate')],2)
q('B',7,'Orthogonal eigenvectors','Prove that eigenvectors belonging to distinct eigenvalues of a Hermitian operator are orthogonal.',
  'Hermitian Operator|Eigenvalue|Eigenvector|Orthogonality|Inner Product|Complex Conjugate',r'1. Let $A|u\rangle=a|u\rangle$ and $A|v\rangle=b|v\rangle$, with distinct real $a,b$.\n2. $\langle u|Av\rangle=b\langle u|v\rangle$, while Hermiticity gives $\langle Au|v\rangle=a\langle u|v\rangle$.\n3. Therefore $(b-a)\langle u|v\rangle=0$. Since $a\ne b$, $\langle u|v\rangle=0$, which proves orthogonality.',[
  s('First, name the two eigenvalues and assume…',r'$a\ne b$',r'$a=b$',r'$a+b=0$','Distinctness enables the final division.','Eigenvalue'),
  s('What relation follows from Hermiticity?',r'$(b-a)\langle u|v\rangle=0$',r'$\langle u|v\rangle=1$',r'$a=b$','Evaluate the same overlap in two ways.','Hermitian Operator'),
  s('Therefore the overlap must be…',r'$0$',[r'$1$'][0],r'$b-a$','Divide by the nonzero eigenvalue difference.','Orthogonality')],2)
q('B',8,'A ket as a column','Write the matrix representation of the ket |ψ⟩ = a |1⟩ + b |2⟩, in the basis {|1⟩, |2⟩}.',
  'Matrix Representation|Ket|Basis|Coordinate',r'1. In the stated ordered basis, the coefficients of $|1\rangle$ and $|2\rangle$ are $a$ and $b$.\n2. Thus the matrix representation is $|\psi\rangle\leftrightarrow\begin{pmatrix}a\\b\end{pmatrix}$. The ket uses the coefficients themselves, not their complex conjugates.',[
  s('What is the first entry of the ket column?','a',['a*'][0],'b','Use the coefficient of the first basis vector.','Matrix Representation'),
  s('Which is the state column?',r'$\begin{pmatrix}a\\b\end{pmatrix}$',r'$(a^*,b^*)$',r'$\begin{pmatrix}b\\a\end{pmatrix}$','Keep the specified basis order.','Ket')],2)
q('B',9,'An operator as a matrix','Find the matrix representation of the operator Â = 2|1⟩⟨1| + 3|2⟩⟨2|.',
  'Matrix Representation|Projection Operator|Orthonormal Basis|Linear Operator',r'1. Assume $|1\rangle,|2\rangle$ are the ordered orthonormal basis. Compute $A|1\rangle=2|1\rangle$ and $A|2\rangle=3|2\rangle$.\n2. These results give the first and second columns: $A=\begin{pmatrix}2&0\\0&3\end{pmatrix}$.',[
  s('First, calculate the action on |1⟩. It is…',r'$2|1\rangle$',r'$3|2\rangle$',r'$2|1\rangle+3|2\rangle$','Orthogonality removes the other projection.','Projection Operator'),
  s('The off-diagonal entries are…',r'$0$',r'$2$',r'$3$','Each input stays along its own basis vector.','Matrix Representation')],2)
q('B',10,'Changing a basis','Show how an operator transforms under a change of basis.',
  'Change of Basis|Matrix Representation|Unitary Operator|Hermitian Adjoint|Orthonormal Basis',r'1. Define $U_{ij}=\langle i|e_j\rangle$: its columns are the new orthonormal basis vectors in old coordinates, and $U$ is unitary.\n2. The new entries are $A\prime_{mn}=\langle e_m|A|e_n\rangle=\sum_{ij}U_{im}^*A_{ij}U_{jn}$.\n3. Thus $A\prime=U^\dagger AU$ and state coordinates transform as $c\prime=U^\dagger c$. A general invertible nonorthonormal basis matrix $S$ gives $S^{-1}AS$ instead.',[
  s('First, what are U’s columns?','New basis vectors in old coordinates','Old basis vectors in new coordinates','The eigenvalues only','State the convention before the formula.','Change of Basis'),
  s('The transformed operator is…',r'$U^\dagger AU$',r'$UAU$',r'$A+U$','Change coordinates in both input and output.','Change of Basis'),
  s('For a nonorthonormal change S, use…',r'$S^{-1}AS$',r'$S^\dagger AS$ always',r'$SAS$','Adjoint equals inverse only when unitary.','Unitary Operator')],2)
q('B',11,'Fourier transform & probability','Explain how the position-space and momentum-space wave functions are related by a Fourier transform. Write the integral transformation from ψ(x) to ϕ(p). Explain the physical meaning of |ψ(x)|² and |ϕ(p)|².',
  'Fourier Transform|Position Representation|Momentum Representation|Probability Density|Continuous Basis|Planck Constant',r'1. With $\langle x|p\rangle=(2\pi\hbar)^{-1/2}e^{ipx/\hbar}$, inserting position completeness gives $\phi(p)=\langle p|\psi\rangle=(2\pi\hbar)^{-1/2}\int e^{-ipx/\hbar}\psi(x)dx$.\n2. The inverse is $\psi(x)=(2\pi\hbar)^{-1/2}\int e^{ipx/\hbar}\phi(p)dp$.\n3. $|\psi(x)|^2$ and $|\phi(p)|^2$ are position and momentum probability densities. Probabilities are obtained by integrating them over intervals; both full integrals are 1 for a normalized state.',[
  s('First, which completeness relation goes into ⟨p|ψ⟩?',r'$\int|x\rangle\langle x|dx=I$',r'$\sum_p p=I$',r'$\int\psi\,dx=I$','Insert the position basis.','Completeness Relation'),
  s('Which is the forward exponential?',r'$e^{-ipx/\hbar}$',r'$e^{ipx/\hbar}$',r'$e^{-px}$','Conjugate the position-to-momentum overlap.','Fourier Transform'),
  s('What does |ψ(x)|² mean?','Probability density','Probability at one exact point','The wave function itself','Integrate over a region to obtain probability.','Probability Density')],2)
q('B',12,'A 2 × 2 Hermitian operator','In a two-dimensional Hilbert space spanned by the orthonormal basis {|1⟩, |2⟩} an operator Â acts on the basis vectors as follows:\nÂ|1⟩ = 2|1⟩ + i|2⟩ and Â|1⟩ = −i|1⟩ + 3|2⟩\n• Construct the 2 × 2 matrix representation of Â.\n• Determine whether Â is Hermitian.\n• Find the eigenvalues of Â.',
  'Matrix Representation|Hermitian Operator|Hermitian Adjoint|Eigenvalue|Secular Equation|Determinant',r'1. Source correction needed: the PDF repeats $A|1\rangle$ for two different outputs. Taken literally, no operator satisfies both. Assuming the second input is the intended $|2\rangle$, proceed conditionally.\n2. The output coefficients form columns: $A=\begin{pmatrix}2&-i\\i&3\end{pmatrix}$.\n3. Its conjugate transpose equals itself, so it is Hermitian.\n4. $\det(A-\lambda I)=(2-\lambda)(3-\lambda)-(-i)(i)=\lambda^2-5\lambda+5=0$. Hence $\lambda_\pm=(5\pm\sqrt5)/2$. The sum is 5 and product is 5, consistent with trace and determinant.',[
  s('What must be checked before solving?','The repeated input ket in the source','Whether 2 is complex','Whether i is zero','The two stated actions on |1⟩ conflict.','Matrix Representation'),
  s('If the second input is |2⟩, which is the first column?',r'$\begin{pmatrix}2\\i\end{pmatrix}$',r'$\begin{pmatrix}2\\-i\end{pmatrix}$',r'$\begin{pmatrix}-i\\3\end{pmatrix}$','Columns come from action on the ordered inputs.','Matrix Representation'),
  s('The matrix is Hermitian because…',r'$A^\dagger=A$',r'$A^T=A$',r'$A^2=I$','Conjugation reverses the signs of the imaginary entries.','Hermitian Operator'),
  s('Which characteristic polynomial is correct?',r'$\lambda^2-5\lambda+5$',r'$\lambda^2-5\lambda+7$',r'$\lambda^2+5\lambda+5$','The off-diagonal product is 1, which is subtracted.','Determinant'),
  s('The two eigenvalues are…',r'$(5\pm\sqrt5)/2$',r'$2,3$',r'$(5\pm\sqrt{29})/2$','Apply the quadratic formula.','Eigenvalue')],2,'#verify: The PDF states A|1⟩ twice with conflicting outputs. Confirm that the second input should be |2⟩. The worked answer is conditional on this correction.')
q('B',13,'Derive the Fourier pair','Given a state vector |ψ⟩, its position-space wavefunction is ψ(x) = ⟨x|ψ⟩ and its momentum-space wavefunction is ϕ(p) = ⟨p|ψ⟩. Using the continuous completeness relation, show that ψ(x) and ϕ(p) form a Fourier transform pair.',
  'Ket|Position Representation|Momentum Representation|Continuous Basis|Completeness Relation|Fourier Transform|Planck Constant',r'1. Insert position completeness: $\phi(p)=\langle p|I|\psi\rangle=\int\langle p|x\rangle\langle x|\psi\rangle dx$.\n2. Use $\langle p|x\rangle=(2\pi\hbar)^{-1/2}e^{-ipx/\hbar}$ to obtain $\phi(p)=(2\pi\hbar)^{-1/2}\int e^{-ipx/\hbar}\psi(x)dx$.\n3. Conversely, insert $I=\int|p\rangle\langle p|dp$ into $\psi(x)=\langle x|I|\psi\rangle$ to get $\psi(x)=(2\pi\hbar)^{-1/2}\int e^{ipx/\hbar}\phi(p)dp$. These are the forward and inverse Fourier transforms.',[
  s('First, insert what into ⟨p|ψ⟩?',r'$I=\int|x\rangle\langle x|dx$',r'$I=\int x\,dx$',r'$I=A^\dagger$','Resolve identity in the position basis.','Completeness Relation'),
  s('The kernel ⟨p|x⟩ is the…','Complex conjugate of ⟨x|p⟩','Same phase as ⟨x|p⟩','Probability density','Conjugate symmetry flips the phase.','Complex Conjugate'),
  s('To derive the inverse, insert…','Momentum completeness','The trace of ψ','A discrete sum over x','Use the other continuous basis.','Continuous Basis')],3)

q('C',1,'Three Hermitian theorems','Hermitian operators represent physical observables in quantum mechanics.\nFormulate and prove the three major theorems concerning Hermitian operators:\n• Theorem 1: The eigenvalues of a Hermitian operator are strictly real.\n• Theorem 2: The eigenvectors of a Hermitian operator corresponding to distinct eigenvalues are mutually orthogonal.\n• Theorem 3: The eigenvectors of a Hermitian operator form a complete orthonormal basis for the vector space.',
  'Hermitian Operator|Observable|Eigenvalue|Eigenvector|Orthogonality|Orthonormal Basis|Spectral Theorem|Degeneracy|Completeness Relation|Dimension',r'Assume a finite-dimensional complex inner-product space. In infinite dimensions the discrete-eigenbasis claim requires extra hypotheses and is not generally true.\n\n(a) Real eigenvalues. Let $Av=\lambda v$, $v\ne0$. Hermiticity gives $\lambda\langle v|v\rangle=\langle v|Av\rangle=\langle Av|v\rangle=\lambda^*\langle v|v\rangle$. Positive norm implies $\lambda=\lambda^*$.\n\n(b) Orthogonality. If $Au=au$, $Av=bv$ with $a\ne b$, then $b\langle u|v\rangle=\langle u|Av\rangle=\langle Au|v\rangle=a\langle u|v\rangle$. Hence $\langle u|v\rangle=0$.\n\n(c) Complete orthonormal eigenbasis. A finite complex matrix has an eigenvalue because its characteristic polynomial has a root. Normalize an eigenvector $e_1$. Its orthogonal complement is preserved by $A$: for $w$ orthogonal to $e_1$, $\langle e_1|Aw\rangle=\langle Ae_1|w\rangle=\lambda_1\langle e_1|w\rangle=0$. The restriction of $A$ to that complement remains Hermitian. Repeat by induction on dimension to obtain $n$ orthonormal eigenvectors spanning the space. Degenerate eigenspaces allow a choice of orthonormal vectors. Thus $\sum_j|e_j\rangle\langle e_j|=I$ and $A=\sum_j\lambda_j|e_j\rangle\langle e_j|$. Individual arbitrary eigenvectors need not already be normalized or orthogonal inside a degenerate eigenspace.',[
  s('First, what qualification is needed for the discrete-basis theorem?','Finite dimension, or additional spectral assumptions','No assumptions at all','Eigenvalues must be positive','Continuous spectra invalidate the unqualified version.','Spectral Theorem'),
  s('For real eigenvalues, compare which two quantities?',r'$\langle v|Av\rangle$ and $\langle Av|v\rangle$',r'$\det A$ and $\operatorname{tr}A$',r'$A$ and $I$','Hermiticity equates these two inner products.','Hermitian Operator'),
  s('For distinct eigenvalues a,b, what forces zero overlap?',r'$(b-a)\langle u|v\rangle=0$',r'$a+b=0$',r'$\|u\|=\|v\|$','The difference b−a is nonzero.','Orthogonality'),
  s('To prove completeness by induction, choose…','A normalized eigenvector and its orthogonal complement','Only all nonzero matrix entries','A momentum eigenket','Reduce the dimension by one.','Spectral Theorem'),
  s('Why does A preserve the orthogonal complement?','Hermiticity makes its overlap with the chosen eigenvector zero','Every vector has eigenvalue zero','A maps every vector to itself','Move A across the inner product.','Hermitian Operator'),
  s('What is the final completeness relation?',r'$\sum_j|e_j\rangle\langle e_j|=I$',r'$\sum_j\lambda_j=I$',r'$\sum_j|e_j\rangle=0$','All eigenbasis projections reconstruct any vector.','Completeness Relation')],3,'#verify: Theorem 3 in the source lacks a finite-dimensional or suitable discrete-spectrum assumption. We prove the finite-dimensional version; arbitrary eigenvectors within a degeneracy are not automatically orthonormal.')
q('C',2,'From Schwarz to Heisenberg','• Starting from the Schwarz inequality for two state vectors |α⟩ = (Â − ⟨Â⟩)|ψ⟩ and |β⟩ = (B̂ − ⟨B̂⟩)|ψ⟩, derive the generalized Robertson-Schrödinger uncertainty relation for any two Hermitian operators Â and B̂: ΔÂ ΔB̂ ≥ ½ |⟨[Â, B̂]⟩|\n• Apply this general relation to position x̂ and momentum p̂ₓ to obtain the classic Heisenberg Uncertainty Principle Δx̂ Δp̂ₓ ≥ ℏ/2',
  'Robertson–Schrödinger Relation|Uncertainty Relation|Schwarz Inequality|Expectation Value|Variance|Covariance|Anticommutator|Commutator|Heisenberg Uncertainty Principle|Position Operator|Momentum Operator',r'(a) Center the observables. For normalized $\psi$ and suitable domains, define $A\prime=A-\langle A\rangle I$, $B\prime=B-\langle B\rangle I$, $\alpha=A\prime\psi$, $\beta=B\prime\psi$. Then $\langle\alpha|\alpha\rangle=(\Delta A)^2$ and similarly for $B$.\n\n(b) Apply Schwarz. $(\Delta A)^2(\Delta B)^2\ge|\langle A\prime B\prime\rangle|^2$. Decompose $A\prime B\prime=\tfrac12\{A\prime,B\prime\}+\tfrac12[A,B]$. The expected first term is real and the second purely imaginary, so $|\langle A\prime B\prime\rangle|^2=\operatorname{Cov}(A,B)^2+\tfrac14|\langle[A,B]\rangle|^2$. This is the full Robertson–Schrödinger bound.\n\n(c) Obtain the relation printed in the question. Drop the nonnegative covariance square and take square roots: $\Delta A\Delta B\ge\tfrac12|\langle[A,B]\rangle|$. This weaker form is the Robertson relation.\n\n(d) Position and momentum. Use $[x,p_x]=i\hbar I$, whose expectation in a normalized state is $i\hbar$. Therefore $\Delta x\Delta p_x\ge\hbar/2$. The spreads are standard deviations across repeated preparations, with finite variances assumed.',[
  s('First, how are the vectors α and β built?','Apply centered observables to ψ','Multiply their means','Differentiate ψ twice','Subtract the expectations before acting.','Variance'),
  s('Schwarz bounds the product of variances by…',r'$|\langle A\prime B\prime\rangle|^2$',r'$\langle A\rangle+\langle B\rangle$',r'$\operatorname{tr}A$','It bounds the overlap of the centered vectors.','Schwarz Inequality'),
  s('How do we split the centered product?',r'$\tfrac12\{A\prime,B\prime\}+\tfrac12[A,B]$',r'$[A,B]$ only',r'$A\prime+B\prime$','Use its symmetric and antisymmetric parts.','Anticommutator'),
  s('Which term is missing from the printed weaker bound?',r'$\operatorname{Cov}(A,B)^2$','The imaginary unit alone','The state vector','The full relation includes correlation.','Robertson–Schrödinger Relation'),
  s('For x and p, insert which commutator?',r'$[x,p]=i\hbar I$',r'$[x,p]=0$',r'$[x,p]=\hbar^2 I$','This is the canonical commutation relation.','Commutator'),
  s('The resulting bound is…',r'$\Delta x\Delta p\ge\hbar/2$',r'$\Delta x\Delta p=0$',r'$\Delta x\Delta p\ge\hbar^2$','Take the magnitude of iℏ and divide by 2.','Heisenberg Uncertainty Principle')],3,'#verify: The source labels the weaker Robertson bound as Robertson–Schrödinger. The answer derives the full covariance-inclusive relation and then the printed bound.')
q('C',3,'Matrices, spectra & invariants','• Explain how a state vector |ψ⟩ is represented as a column matrix and an operator Â is represented as a square matrix in a discrete orthonormal basis {|ϕₙ⟩}.\n• Formulate the matrix eigenvalue problem Â |ψ⟩ = λ|ψ⟩ as a secular equation det(A − λ I) = 0\n• Demonstrate how a unitary transformation Û diagonalizes a Hermitian matrix representation.\n• Prove that the trace and eigenvalues of an operator are invariant under unitary transformations.',
  'Matrix Representation|Matrix|Orthonormal Basis|Ket|Linear Operator|Eigenvalue|Eigenvector|Secular Equation|Determinant|Unitary Operator|Change of Basis|Trace|Spectral Theorem',r'Assume finite dimension $n$, so ordinary determinants and finite traces apply.\n\n(a) Representation. $|\psi\rangle=\sum_jc_j|\phi_j\rangle$ with $c_j=\langle\phi_j|\psi\rangle$, so the state is the column $\begin{pmatrix}c_1\\\vdots\\c_n\end{pmatrix}$. The operator has entries $A_{ij}=\langle\phi_i|A|\phi_j\rangle$ and sends $c$ to $Ac$.\n\n(b) Secular equation. $Ac=\lambda c$ is $(A-\lambda I)c=0$. A nonzero solution exists exactly when the square matrix is singular, so $\det(A-\lambda I)=0$.\n\n(c) Unitary diagonalization. The finite spectral theorem supplies orthonormal eigenvectors $u_j$. Put them into the columns of $U$; then $U^\dagger U=I$ and $AU=UD$, where $D=\operatorname{diag}(\lambda_1,\ldots,\lambda_n)$. Therefore $U^\dagger AU=D$.\n\n(d) Trace invariance. Cyclicity gives $\operatorname{tr}(U^\dagger AU)=\operatorname{tr}(AUU^\dagger)=\operatorname{tr}A$.\n\n(e) Eigenvalue invariance. If $Av=\lambda v$, then $(U^\dagger AU)(U^\dagger v)=U^\dagger Av=\lambda U^\dagger v$. Invertibility makes $U^\dagger v\ne0$. The inverse map gives the converse, and the characteristic polynomials agree: $\det(U^\dagger(A-\lambda I)U)=\det(A-\lambda I)$. Thus eigenvalues and multiplicities are preserved.',[
  s('First, what is the ith state coefficient?',r'$c_i=\langle\phi_i|\psi\rangle$',r'$c_i=\langle\psi|\phi_i\rangle$ always',r'$c_i=\lambda_i$','Project onto each basis bra.','Matrix Representation'),
  s('Operator matrix entry $A_{ij}$ is…',r'$\langle\phi_i|A|\phi_j\rangle$',r'$\langle\phi_j|A|\phi_i\rangle$',r'$\lambda_i\lambda_j$','Output row i, input column j.','Matrix Representation'),
  s(r'A nonzero solution of $(A-\lambda I)c=0$ requires…',r'$\det(A-\lambda I)=0$',r'$\det(A-\lambda I)=1$',r'$c=0$','The matrix must be singular.','Secular Equation'),
  s('What belongs in U’s columns to diagonalize A?','Orthonormal eigenvectors','Eigenvalues alone','Arbitrary vectors of any length','They form the eigenbasis.','Unitary Operator'),
  s('Which expression is diagonal?',r'$U^\dagger AU$',r'$UAU$',r'$U+A$','Our convention puts the new basis in U columns.','Change of Basis'),
  s('Which property proves trace invariance?','Cyclicity and UU†=I','Commutativity of all matrices','All traces equal zero','Move the first factor to the end.','Trace'),
  s('If v is an eigenvector of A, the transformed eigenvector is…',r'$U^\dagger v$',r'$\lambda U$',r'$Uv$ under this convention','Transform the coordinates with U†.','Eigenvector')],3)
q('C',4,'Continuous bases & operators','• Define the continuous position basis states {|x⟩} and momentum basis states {|p⟩}, stating their delta-function normalization and completeness relations.\n• By solving the differential momentum eigenvalue equation p̂ = p⃗|p⃗⟩ in position representation, derive the scalar product (transformation function):\n⟨x|p⟩ = √(1/(2πℏ)) eⁱᵖˣ/ℏ\n• Using this result, prove that the position operator acts as x̂ and the momentum operator acts as −iℏ ∂/∂x in position space.',
  'Continuous Basis|Delta Function|Completeness Relation|Position Operator|Momentum Operator|Fourier Transform|Exponential Function|Derivative|Planck Constant|Integration by Parts|Boundary Condition|Operator Domain',r'(a) Continuous bases. In one dimension, $\langle x|x\prime\rangle=\delta(x-x\prime)$, $\int|x\rangle\langle x|dx=I$; likewise $\langle p|p\prime\rangle=\delta(p-p\prime)$ and $\int|p\rangle\langle p|dp=I$. These kets are generalized states.\n\n(b) Transformation function. Write $u_p(x)=\langle x|p\rangle$. Solving the stated differential momentum eigenvalue equation $-i\hbar\,du_p/dx=pu_p$ gives $u_p(x)=C e^{ipx/\hbar}$. Enforce $\langle p|p\prime\rangle=|C|^2\int e^{i(p\prime-p)x/\hbar}dx=|C|^2(2\pi\hbar)\delta(p\prime-p)$. Hence choose $C=(2\pi\hbar)^{-1/2}$; the phase convention is chosen to be zero. The normalization calculation is distributional.\n\n(c) Position action. Because $\langle x|\hat x=x\langle x|$, $\langle x|\hat x|\psi\rangle=x\psi(x)$: position acts by multiplication.\n\n(d) Momentum action from the kernel. Expand $\psi(x)=(2\pi\hbar)^{-1/2}\int e^{ipx/\hbar}\phi(p)dp$. Then $\langle x|\hat p|\psi\rangle=(2\pi\hbar)^{-1/2}\int p\,e^{ipx/\hbar}\phi(p)dp=-i\hbar\,d\psi/dx$. Interchanging derivative and integral is justified for sufficiently regular states, and the result extends on the suitable operator domain.\n\n(e) Domain qualification. These operators need specified domains. Integration by parts confirms momentum symmetry when the boundary term vanishes; full self-adjointness also requires the appropriate adjoint domain. The differential form in part (b) is the given starting equation, while part (d) verifies its action on general regular wavepackets.',[
  s('First, how are position basis overlaps normalized?',r'$\langle x|x\prime\rangle=\delta(x-x\prime)$',r'$\langle x|x\prime\rangle=1$',r'$\langle x|x\prime\rangle=x+x\prime$','A continuous label uses delta normalization.','Delta Function'),
  s('Which differential equation is solved for the kernel?',r'$-i\hbar u_p\prime(x)=p u_p(x)$',r'$u_p\prime(x)=x^2$',r'$u_p(x)=0$','Use the momentum eigenvalue equation.','Momentum Operator'),
  s('What is its solution form?',r'$C e^{ipx/\hbar}$',r'$C e^{-px/\hbar}$',r'$Cx^2$','The derivative reproduces the momentum eigenvalue.','Exponential Function'),
  s('Delta normalization fixes the magnitude of C to…',r'$(2\pi\hbar)^{-1/2}$',r'$2\pi\hbar$',r'$1$','The oscillatory integral is 2πℏ times a delta.','Continuous Basis'),
  s('How does x̂ act in position space?','Multiply by x','Multiply by p','Differentiate twice','Position basis states have eigenvalue x.','Position Operator'),
  s('Why does momentum become a derivative?','Differentiating the kernel brings down ip/ℏ','Every wave function is constant','The trace equals p','Then multiply by −iℏ.','Momentum Operator'),
  s('For integration-by-parts symmetry, what must be addressed?','Boundary terms and operator domain','Only matrix size','Only the state’s name','State regularity and boundary assumptions matter.','Boundary Condition')],4,'#verify: The source momentum eigenvalue equation is malformed. We use the intended one-dimensional equation p̂|p⟩=p|p⟩, keeping the original source text separately.')

# Add prerequisites needed for the proofs, beyond the initial shared foundations.
c('Polynomial','matrices',r'\sum c_kx^k','Function|Integer|Basic Algebra','A finite sum of nonnegative integer powers with numerical coefficients.',r'$f(x)=\sum_{k=0}^n c_kx^k$, where $n$ is a nonnegative integer and each $c_k$ is a scalar.',r'$x^2-5x+5$ is a polynomial.','Which is a polynomial?',r'$x^2+1$',[r'$1/x$',r'$\sqrt x$'],'The exponents are nonnegative integers.')
c('Fundamental Theorem of Algebra','matrices',r'\exists\lambda','Polynomial|Complex Number Arithmetic','Every nonconstant polynomial with complex coefficients has a complex root.',r'If $p(z)$ is a nonconstant complex polynomial, there exists a complex number $\lambda$ with $p(\lambda)=0$. A degree-n polynomial has n roots counted with their repeated occurrences.',r'$z^2+1$ has roots $i$ and $-i$.','Over the complex numbers, a nonconstant polynomial…','Has at least one root',['May have no roots','Has only real roots'],'This guarantees a finite complex matrix has an eigenvalue.')
c('Mathematical Induction','ground',r'n\to n+1','Integer|Axiom','A proof that starts with one case and shows how to pass to the next.',r'Prove a statement for $n=1$, then prove that its truth for $n$ implies its truth for $n+1$. It then holds for all positive integers.',r'The finite spectral-theorem proof reduces dimension until the one-dimensional case.','An induction proof needs…','A base case and an implication to the next case',['Only many numerical examples','Only the final case'],'Both steps are essential.')
c('Orthogonal Complement','spaces',r'W^\perp','Orthogonality|Vector Space|Set','All vectors perpendicular to every vector in a chosen subspace.',r'$W^\perp=\{v:\langle w|v\rangle=0\text{ for every }w\in W\}$.',r'The orthogonal complement of the horizontal line in $\mathbb R^2$ is the vertical line.','What complements the span of (1,0) in ℝ²?','The span of (0,1)',['The span of (1,1)','All of ℝ²'],'Require zero inner product with (1,0).')
c('Eigenspace','eigen',r'\ker(A-\lambda I)','Eigenvalue|Vector Space|Zero Vector','All vectors having a chosen eigenvalue, with the zero vector included.',r'The eigenspace for $\lambda$ is $E_\lambda=\{v:Av=\lambda v\}$. It is a vector space; its nonzero members are eigenvectors.',r'For $A=2I$, $E_2$ is the entire space.','Does an eigenspace include zero?','Yes',['No','Only if λ=0'],'The subspace includes zero although an eigenvector must be nonzero.')

# Vocabulary used inside formal definitions is also explicitly explained.
c('Associativity','spaces',r'(a+b)+c','Basic Algebra','Grouping three additions or multiplications does not change the result.',r'An operation is associative if $(a+b)+c=a+(b+c)$; for multiplication, $(ab)c=a(bc)$.',r'$(1+2)+3=1+(2+3)=6$.','Associativity changes…','The grouping',['The order of entries','The signs'],'Parentheses change but the order stays fixed.', ['associative'])
c('Commutativity','spaces',r'a+b=b+a','Basic Algebra','Swapping the order of two inputs leaves an operation unchanged.',r'Addition is commutative when $a+b=b+a$; multiplication is commutative when $ab=ba$. Matrix multiplication need not be commutative.',r'$2+3=3+2$.','Commutativity changes…','The input order',['The grouping only','The number of terms'],'Swapping two inputs is the defining test.', ['commutative'])
c('Distributivity','spaces',r'a(b+c)','Basic Algebra','Multiplication spreads across a sum.',r'$a(b+c)=ab+ac$. Vector-space scalar multiplication obeys $a(u+v)=au+av$ and $(a+b)v=av+bv$.',r'$2(3+4)=2\cdot3+2\cdot4=14$.','Expand $a(u+v)$.',r'$au+av$',[r'$au+v$',r'$a+u+v$'],'Multiply both summands.', ['distributive'])
c('Positive Definiteness','spaces',r'\langle v|v\rangle>0','Vector|Real Number|Zero Vector','A rule assigns a positive self-value to every nonzero vector.',r'A pairing is positive definite when its self-value is real and positive for each nonzero vector, and is zero for the zero vector.',r'The sum $|v_1|^2+|v_2|^2$ is positive unless both entries vanish.','A nonzero vector has which self-value in a positive-definite pairing?','Strictly positive',['Zero','Negative'],'Only the zero vector may have self-value zero.', ['positive definite','positive definiteness'])
c('Transpose','matrices',r'A^T','Matrix','Swap the rows and columns of a matrix.',r'$(A^T)_{ij}=A_{ji}$. Transposition alone does not complex-conjugate entries.',r'The transpose of $\begin{pmatrix}1\\i\end{pmatrix}$ is $(1,i)$.','Transposition alone changes i to…',r'$i$',[r'$-i$',r'$1$'],'Conjugation is a separate operation.', ['transposed'])
c('Inverse Matrix','matrices',r'A^{-1}','Matrix|Identity Operator','A matrix that reverses another matrix’s action.',r'For a square matrix, $A^{-1}A=AA^{-1}=I$. An inverse exists exactly when the determinant is nonzero.',r'$\operatorname{diag}(2,3)^{-1}=\operatorname{diag}(1/2,1/3)$.','What must an inverse satisfy?',r'$A^{-1}A=I$',[r'$A^{-1}A=0$',r'$A^{-1}=A$ always'],'Composing an action with its inverse returns the input.', ['invertible','invertibility','inverse'])
c('Diagonal Matrix','matrices',r'D','Matrix','A square matrix whose entries outside the main diagonal are zero.',r'$D_{ij}=0$ whenever $i\ne j$; its diagonal entries are $D_{ii}$.',r'$\begin{pmatrix}2&0\\0&3\end{pmatrix}$ is diagonal.','Which entries must vanish in a diagonal matrix?','All off-diagonal entries',['All diagonal entries','All entries'],'Only the main diagonal can carry nonzero numbers.', ['diagonal','off-diagonal'])
c('Polynomial Root','matrices',r'p(\lambda)=0','Polynomial|Function','An input making a polynomial’s output zero.',r'$\lambda$ is a root of $p$ if $p(\lambda)=0$.',r'2 and 3 are roots of $(x-2)(x-3)$.','A root of p satisfies…',r'$p(\lambda)=0$',[r'$p(\lambda)=1$',r'$p(0)=\lambda$'],'Substituting the root makes the output zero.', ['root','roots'])
c('Multiplicity','eigen',r'm_\lambda','Polynomial Root|Integer|Degeneracy','The number of times a value appears as a repeated polynomial root.',r'Algebraic multiplicity of an eigenvalue is its multiplicity as a root of $\det(A-\lambda I)$. For Hermitian matrices it equals the dimension of the eigenspace.',r'For $2I$ in two dimensions, $(2-\lambda)^2$ gives multiplicity 2.',r'The root 2 in $(\lambda-2)^2$ has multiplicity…',r'$2$',[r'$1$',r'$0$'],'Count the repeated factor.', ['multiplicities'])
c('Spectrum','eigen',r'\sigma(A)','Eigenvalue|Inverse Matrix|Operator Domain','The set of values where subtracting that value times identity does not have a suitable inverse.',r'For a finite matrix, the spectrum is its set of eigenvalues. In infinite dimensions, the spectrum includes continuous values where the inverse fails to be a bounded operator defined on the whole space; bounded means the output norm is at most a fixed constant times the input norm.',r'Position on the real line has continuous spectrum, not a discrete normalizable eigenbasis.','In finite dimensions, the spectrum is…','The set of eigenvalues',['The diagonal of every basis representation','The trace only'],'In infinite dimensions there can also be continuous parts.', ['spectra','continuous spectrum','discrete spectrum'])
c('Test Function','waves',r'f\in C_c^\infty','Function|Derivative','A smooth input function used to probe a distribution.',r'A test function here has derivatives of all orders and vanishes outside some bounded interval. Distributions act on such functions.',r'A smooth bump that is zero outside $[-1,1]$ is a test function.','A test function used here is…','Smooth and zero outside a bounded region',['Always a plane wave','Always a constant on the whole line'],'These conditions make distributional probing well-defined.', ['test functions','smooth test functions'])
c('Compact Support','waves',r'\operatorname{supp} f','Function|Set|Real Number','A function is zero beyond a finite region.',r'On the real line, a function has compact support when it vanishes outside some closed bounded interval.',r'A function zero for $|x|>1$ has compact support.','Compact support on the line means…','Zero outside some finite closed interval',['Never zero','Infinite nonzero tails'],'Its nonzero part fits in a finite region.', ['compact support'])
c('Generalized State','states',r'|x\rangle','Ket|Distribution','An idealized state symbol interpreted through its action on suitable functions.',r'Continuous-basis kets such as $|x\rangle$ or $|p\rangle$ are generalized states. They are described distributionally, and need not belong to the ordinary Hilbert space of normalizable states.',r'Exact position states obey delta normalization.','An exact position ket is usually…','A generalized state',['An ordinary unit vector in L²','A scalar'],'Its normalization is distributional.', ['generalized states','generalized state','generalized'])
c('Probability Amplitude','waves',r'\psi','Complex Number Arithmetic|Absolute Value|Probability Density','A complex number whose squared magnitude gives a probability or density.',r'A state coefficient is a probability amplitude; its squared absolute value gives a discrete probability, or a density for continuously labelled states.',r'Amplitude $i/\sqrt2$ has squared magnitude $1/2$.',r'What is the squared magnitude of $i/\sqrt2$?',r'$1/2$',[r'$i/2$',r'$1$'],'Multiply by the conjugate.', ['amplitude','amplitudes'])
c('Phase','waves',r'e^{i\theta}','Complex Number Arithmetic|Exponential Function','The angle describing the direction of a complex number.',r'A nonzero complex number is $z=|z|e^{i\theta}$; $\theta$ is its phase. Multiplying an entire state by $e^{i\theta}$ gives a global phase without changing probabilities; relative phases between coefficients can change interference.',r'$i$ has phase $\pi/2$ relative to positive real numbers.','Does a common global phase change probabilities?','No',['Yes, always','Only if the phase is π'],'Its absolute value is one.', ['global phase','overall phase','phase convention','phase'])
c('Superposition','states',r'a|u\rangle+b|v\rangle','Linear Combination|Ket','A quantum state made by adding scaled state vectors.',r'$a|u\rangle+b|v\rangle$ is a superposition; it is normalized separately when needed.',r'$(|1\rangle+|2\rangle)/\sqrt2$ is normalized for orthonormal basis states.','A superposition is…','A linear combination of state vectors',['An eigenvalue product','A trace'],'Add scaled kets.', ['superpositions'])
c('Symmetric Operator','operators',r'\langle u|Av\rangle','Hermitian Adjoint|Operator Domain','An operator whose action can move across an inner product on its own domain.',r'$\langle u|Av\rangle=\langle Au|v\rangle$ for all $u,v\in D(A)$. For unbounded operators this need not imply $D(A)=D(A^\dagger)$, so it need not imply self-adjointness.',r'A derivative can satisfy the symmetry identity on a restricted domain without being self-adjoint.','Does symmetry alone settle self-adjointness for unbounded operators?','No; domains still matter',['Yes, always','Only if the eigenvalues are integers'],'The adjoint domain may be larger.', ['symmetry identity'])
c('Null Space','matrices',r'\ker A','Matrix|Zero Vector|Set','All vectors that a linear map sends to zero.',r'$\ker A=\{v:Av=0\}$. A square finite matrix is singular when its null space contains a nonzero vector.',r'$\operatorname{diag}(1,0)$ sends every $\begin{pmatrix}0\\b\end{pmatrix}$ to zero.','A vector in the null space satisfies…',r'$Av=0$',[r'$Av=v$',r'$A=0$'],'The matrix can be nonzero while annihilating some vectors.', ['null space','singular'])
c('Antisymmetric Part','operators',r'(AB-BA)/2','Commutator|Operator Product','The half-difference between two opposite-order products.',r'$AB=\tfrac12(AB+BA)+\tfrac12(AB-BA)$. The second term is the antisymmetric part under swapping $A,B$.',r'It changes sign when A and B are exchanged.','Swapping A and B changes the antisymmetric part’s sign to…','Its negative',['The same sign','Always zero'],'The reversed difference is BA−AB.', ['antisymmetric part'])
c('Symmetric Part','operators',r'(AB+BA)/2','Anticommutator|Operator Product','The half-sum of two opposite-order products.',r'The symmetric part is $\tfrac12(AB+BA)$ and is unchanged under exchanging $A$ and $B$.',r'For $A=B$ the symmetric part is $A^2$.','The symmetric part of AB is…',r'$(AB+BA)/2$',[r'$(AB-BA)/2$',r'$AB/2$'],'Use the half-sum.', ['symmetric part'])


c('Mathematical Space','spaces',r'S','Set|Axiom','A collection of objects equipped with specified rules or relationships.',r'A mathematical space consists of a set together with additional structure, such as rules for adding its elements or measuring distances between them. Its definition specifies exactly which rules are required.',r'A vector space adds addition and scaling rules to a set of vectors.','What makes a set a mathematical space?','Specified additional structure',['Its name alone','It must contain three elements'],'A space is a set plus the rules under discussion.', ['space','spaces'])
c('Probability','waves',r'P(E)','Set|Real Number|Basic Algebra','A number from zero to one measuring how likely an outcome is.',r'For an event, a set of outcomes, $0\le P(E)\le1$. The entire outcome set has probability 1. Probabilities of disjoint events add; disjoint means sharing no outcome.',r'A fair two-outcome experiment gives probability $1/2$ for either result.','A probability must lie in…',r'$[0,1]$',[r'$[-1,1]$',r'$[1,\infty)$'],'Zero means impossible and one means certain.', ['probabilities'])
c('Continuity','waves',r'f(x_n)\to f(x)','Function|Limit|Absolute Value','Small input changes near a point produce arbitrarily small output changes.',r'A real or complex function is continuous at $x$ when for every $\epsilon>0$ some $\delta>0$ makes $|f(y)-f(x)|<\epsilon$ whenever $|y-x|<\delta$. More general spaces use their specified notions of closeness.',r'$f(x)=x^2$ is continuous at every real x.','Continuity compares…','Nearby inputs and their outputs',['Only integer inputs','Only the function name'],'Outputs must become close when inputs become sufficiently close.', ['continuous'])
c('Triangle Inequality','spaces',r'\|u+v\|','Norm|Vector','The length of a sum does not exceed the sum of the lengths.',r'$\|u+v\|\le\|u\|+\|v\|$. The norm induced by an inner product satisfies this inequality.',r'For $u=(1,0)$, $v=(0,1)$, $\sqrt2\le2$.','Which is the triangle inequality?',r'$\|u+v\|\le\|u\|+\|v\|$',[r'$\|u+v\|>\|u\|+\|v\|$',r'$\|u+v\|=0$'],'A direct distance cannot exceed a path through an intermediate point.')
c('Normed Space','spaces',r'(V,\|\cdot\|)','Vector Space|Norm|Triangle Inequality','A vector space equipped with a consistent length rule.',r'A normed space has a norm satisfying $\|v\|\ge0$ with equality only for zero, $\|av\|=|a|\|v\|$, and the triangle inequality. Its distance is $d(u,v)=\|u-v\|$. A norm need not arise from an inner product.',r'$\mathbb C^2$ with its usual length is normed.','Does every norm have to arise from an inner product?','No',['Yes','Only over complex numbers'],'Inner-product norms are an important subclass.', ['normed'])
c('Quantum State','states',r'\psi','Hilbert Space|Normalization|Phase','The mathematical description of a system’s preparation used to predict measurement outcomes.',r'A pure state is represented by a normalized vector in a Hilbert space, with vectors differing by a common factor $e^{i\theta}$ representing the same pure state. This module uses pure-state vectors; more general mixed states require a different representation.',r'$\begin{pmatrix}1\\0\end{pmatrix}$ and $i\begin{pmatrix}1\\0\end{pmatrix}$ represent the same pure state.','Do normalized vectors differing only by a global phase represent different pure states?','No',['Yes','Only if the phase equals i'],'The common phase does not change measurement probabilities.', ['quantum state','pure state','pure-state','state'])

